function uid() {
  return Math.random().toString(36).slice(2, 10) + Date.now().toString(36).slice(-4);
}
function todayStr() {
  return new Date().toISOString().slice(0, 10);
}
function monthKey(dateStr) {
  return (dateStr || "").slice(0, 7);
}
function monthLabel(key) {
  if (!key) return "";
  const [y, m] = key.split("-");
  return `${MESES[parseInt(m, 10) - 1]} ${y}`;
}
function money(n) {
  const v = Number(n) || 0;
  return "$" + v.toLocaleString("es-AR", { maximumFractionDigits: 0 });
}
function pct(n) {
  return (Number(n) || 0).toLocaleString("es-AR", { maximumFractionDigits: 1 }) + "%";
}
function excelDateToStr(v) {
  if (v instanceof Date) return v.toISOString().slice(0, 10);
  if (typeof v === "number" && v > 0) {
    const d = new Date(Math.round((v - 25569) * 86400 * 1000));
    return d.toISOString().slice(0, 10);
  }
  if (typeof v === "string") {
    const m = v.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})$/);
    if (m) {
      let [, d, mo, y] = m;
      if (y.length === 2) y = "20" + y;
      return `${y}-${mo.padStart(2, "0")}-${d.padStart(2, "0")}`;
    }
    return v;
  }
  return todayStr();
}
function sumarDias(fechaStr, dias) {
  const d = new Date(fechaStr + "T00:00:00");
  d.setDate(d.getDate() + (Number(dias) || 0));
  return d.toISOString().slice(0, 10);
}
// Determina si, a efectos de caja, una venta ya se considera cobrada:
// - medios inmediatos (sin estadoCobro o "acreditado"): siempre
// - confirmada manualmente: siempre
// - pendiente: se muestra como "acreditada (estimada)" en cuanto pasa la fecha estimada,
//   pero sigue disponible para confirmar/ajustar en Arqueo -> Cobros pendientes
function estaAcreditadaVenta(v) {
  if (v.medioPago === MEDIO_CTA_CTE) return false;
  if (v.confirmado) return true;
  if (!v.estadoCobro || v.estadoCobro === "acreditado") return true;
  return v.fechaEstimadaAcreditacion ? v.fechaEstimadaAcreditacion <= todayStr() : false;
}
