/* ---------- normalización de datos (defaults + migraciones) ----------
   Antes esto vivía adentro de loadData() (que leía de window.storage, el
   almacenamiento del prototipo). Ahora la carga/guardado real la hace
   firestoreSync.js, pero la lógica de "completar valores por defecto y
   migrar datos viejos" es la misma, así que queda acá como función
   exportada para que firestoreSync.js la use después de leer Firestore. */
export function normalizarData(parcial) {
  const merged = { ...defaultData(), ...(parcial || {}) };
  if (!merged.medios.includes(MEDIO_CTA_CTE)) merged.medios = [...merged.medios, MEDIO_CTA_CTE];
  if (!merged.rubros.includes("Comisiones Corredores de Pago")) {
    merged.rubros = [...merged.rubros, "Comisiones Corredores de Pago"];
    merged.rubroTipo = { ...merged.rubroTipo, "Comisiones Corredores de Pago": "variable" };
  }
  if (!merged.medioConfig) merged.medioConfig = {};
  if (!merged.perfilesImportacion) merged.perfilesImportacion = [];
  if (!merged._migroCanalesEcommerce) {
    const nuevosMedios = MEDIOS_ECOMMERCE_DEFAULT.filter((m) => !merged.medios.includes(m));
    if (nuevosMedios.length) {
      merged.medios = [...merged.medios, ...nuevosMedios];
      merged.medioConfig = { ...merged.medioConfig };
      nuevosMedios.forEach((m) => {
        if (!merged.medioConfig[m]) merged.medioConfig[m] = { ...MEDIO_CONFIG_ECOMMERCE_DEFAULT[m] };
      });
    }
    merged._migroCanalesEcommerce = true;
  }
  return merged;
}

