function TagList({ items, onAdd, onRemove, editable = true }) {
  const [val, setVal] = useState("");
  return (
    <div className="flex flex-col gap-2">
      <div className="flex flex-wrap gap-2">
        {items.map((it) => (
          <span
            key={it}
            className="flex items-center gap-1 text-sm"
            style={{ background: C.greenSoft, color: C.greenDark, borderRadius: 999, padding: "4px 10px" }}
          >
            {it}
            {editable && <X size={13} style={{ cursor: "pointer" }} onClick={() => onRemove(it)} />}
          </span>
        ))}
      </div>
      {editable && (
        <div className="flex gap-2">
          <TextInput
            placeholder="Agregar nuevo..."
            value={val}
            onChange={(e) => setVal(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter" && val.trim()) {
                onAdd(val.trim());
                setVal("");
              }
            }}
            style={{ flex: 1 }}
          />
          <Button
            variant="ghost"
            onClick={() => {
              if (val.trim()) {
                onAdd(val.trim());
                setVal("");
              }
            }}
          >
            <Plus size={15} />
          </Button>
        </div>
      )}
    </div>
  );
}
