function deltaInfo(pctValue, invertirColor) {
  if (pctValue === null || pctValue === undefined || !isFinite(pctValue)) return null;
  const positivo = pctValue >= 0;
  const bueno = invertirColor ? !positivo : positivo;
  return {
    text: `${positivo ? "▲" : "▼"} ${Math.abs(pctValue).toFixed(1)}% vs. mes anterior`,
    color: bueno ? C.green : C.rust,
  };
}

