function Dashboard({ data }) {
  const years = useMemo(() => {
    const s = new Set();
    data.ventas.forEach((v) => s.add((v.fecha || "").slice(0, 4)));
    data.gastos.forEach((g) => s.add((g.fecha || "").slice(0, 4)));
    s.add(String(new Date().getFullYear()));
    return Array.from(s).filter(Boolean).sort();
  }, [data]);

  const [year, setYear] = useState(years[years.length - 1] || String(new Date().getFullYear()));
  const [mode, setMode] = useState("mensual");
  const [month, setMonth] = useState(todayStr().slice(0, 7));
  const [rangoDesde, setRangoDesde] = useState(todayStr());
  const [rangoHasta, setRangoHasta] = useState(todayStr());
  const [chartType, setChartType] = useState("bar");

  useEffect(() => {
    if (!years.includes(year)) setYear(years[years.length - 1]);
  }, [years]); // eslint-disable-line

  const flujoAnual = useMemo(() => {
    return MESES.map((m, i) => {
      const key = `${year}-${String(i + 1).padStart(2, "0")}`;
      const ventas = data.ventas.filter((v) => monthKey(v.fecha) === key).reduce((a, v) => a + v.total, 0);
      const gastos = data.gastos.filter((g) => monthKey(g.fecha) === key).reduce((a, g) => a + Number(g.monto), 0);
      return { mes: m, Ventas: ventas, Gastos: gastos };
    });
  }, [data, year]);

  function inRangeFn(fecha) {
    if (mode === "mensual") return monthKey(fecha) === month;
    if (mode === "rango") return fecha >= rangoDesde && fecha <= rangoHasta;
    return (fecha || "").slice(0, 4) === year;
  }
  const periodo = useMemo(() => {
    const ventas = data.ventas.filter((v) => inRangeFn(v.fecha));
    const gastos = data.gastos.filter((g) => inRangeFn(g.fecha));
    const movimientos = (data.movimientos || []).filter((m) => inRangeFn(m.fecha));
    return { ventas, gastos, movimientos };
  }, [data, mode, month, year, rangoDesde, rangoHasta]); // eslint-disable-line

  const totalVentas = periodo.ventas.reduce((a, v) => a + v.total, 0);
  const totalVentasBruto = periodo.ventas.reduce((a, v) => a + (v.totalBruto ?? v.total), 0);
  const totalDescuentos = periodo.ventas.reduce((a, v) => a + (v.descuentoMonto || 0), 0);
  const ticketPromedio = periodo.ventas.length ? totalVentas / periodo.ventas.length : 0;
  const totalGastos = periodo.gastos.reduce((a, g) => a + Number(g.monto), 0);
  const gastosPctIngresos = totalVentas ? (totalGastos / totalVentas) * 100 : 0;
  const porCobrar = data.ventas
    .filter((v) => v.medioPago !== MEDIO_CTA_CTE && v.estadoCobro === "pendiente" && !v.confirmado)
    .reduce((a, v) => a + v.total, 0);
  const totalNoAcreditadoPeriodo = periodo.ventas
    .filter((v) => v.medioPago !== MEDIO_CTA_CTE && v.estadoCobro === "pendiente" && !v.confirmado)
    .reduce((a, v) => a + v.total, 0);
  const totalComisionesPeriodo = periodo.ventas.reduce((a, v) => a + (v.comisionMonto || 0), 0);

  const flujoOperativo = totalVentas - totalNoAcreditadoPeriodo - totalComisionesPeriodo - totalGastos;
  const flujoInversion = periodo.movimientos
    .filter((m) => m.flujo === "inversion")
    .reduce((a, m) => a + (m.tipo === "ingreso" ? m.monto : -m.monto), 0);
  const flujoFinanciamiento = periodo.movimientos
    .filter((m) => m.flujo === "financiamiento")
    .reduce((a, m) => a + (m.tipo === "ingreso" ? m.monto : -m.monto), 0);
  const saldoGlobal = flujoOperativo + flujoInversion + flujoFinanciamiento;

  // comparación contra el mes anterior (solo tiene sentido en modo "un mes")
  function mesAnterior(key) {
    const [y, m] = key.split("-").map(Number);
    const d = new Date(y, m - 2, 1);
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`;
  }
  const comparacion = useMemo(() => {
    if (mode !== "mensual") return null;
    const prevKey = mesAnterior(month);
    const prevVentas = data.ventas.filter((v) => monthKey(v.fecha) === prevKey).reduce((a, v) => a + v.total, 0);
    const prevGastos = data.gastos.filter((g) => monthKey(g.fecha) === prevKey).reduce((a, g) => a + Number(g.monto), 0);
    const delta = (curr, prev) => (prev ? ((curr - prev) / Math.abs(prev)) * 100 : curr ? 100 : null);
    return {
      ventas: delta(totalVentas, prevVentas),
      gastos: delta(totalGastos, prevGastos),
      operativo: delta(flujoOperativo, prevVentas - prevGastos),
    };
  }, [mode, month, data, totalVentas, totalGastos, flujoOperativo]); // eslint-disable-line

  // punto de equilibrio (nivel 1): gastos fijos / margen de contribución
  const gastosFijos = periodo.gastos.filter((g) => (data.rubroTipo || {})[g.rubro] === "fijo").reduce((a, g) => a + Number(g.monto), 0);
  const gastosVariables = periodo.gastos.filter((g) => (data.rubroTipo || {})[g.rubro] === "variable").reduce((a, g) => a + Number(g.monto), 0);
  const margenContribucionPct = totalVentas ? ((totalVentas - gastosVariables) / totalVentas) * 100 : 0;
  const puntoEquilibrio = margenContribucionPct > 0 ? gastosFijos / (margenContribucionPct / 100) : null;

  function groupSum(arr, keyFn, valFn) {
    const m = new Map();
    arr.forEach((it) => {
      const k = keyFn(it) || "Sin dato";
      m.set(k, (m.get(k) || 0) + valFn(it));
    });
    return Array.from(m.entries()).map(([name, value]) => ({ name, value }));
  }

  const porProducto = groupSum(periodo.ventas, (v) => v.productoNombre, (v) => v.total).sort((a, b) => b.value - a.value).slice(0, 8);
  const porProductoCant = groupSum(periodo.ventas, (v) => v.productoNombre, (v) => v.cantidad).sort((a, b) => b.value - a.value).slice(0, 8);
  const porFamilia = groupSum(periodo.ventas, (v) => v.familia, (v) => v.total);
  const porPunto = groupSum(periodo.ventas, (v) => v.puntoVenta, (v) => v.total);
  const porLista = groupSum(periodo.ventas, (v) => v.listaLabel || v.lista, (v) => v.total);
  const porRubro = groupSum(periodo.gastos, (g) => g.rubro, (g) => Number(g.monto)).sort((a, b) => b.value - a.value);

  // solo se muestran estas dos si el negocio realmente usa más de una opción
  const puntosUsados = useMemo(() => new Set(data.ventas.map((v) => v.puntoVenta).filter(Boolean)), [data.ventas]);
  const listasUsadas = useMemo(() => new Set(data.ventas.map((v) => v.listaLabel || v.lista).filter(Boolean)), [data.ventas]);
  const mostrarPorPunto = puntosUsados.size > 1;
  const mostrarPorLista = listasUsadas.size > 1;

  function periodoLabelTexto() {
    if (mode === "mensual") return monthLabel(month);
    if (mode === "rango") return `${rangoDesde} a ${rangoHasta}`;
    return `Año ${year}`;
  }

  function descargarReporte() {
    const periodoLabel = periodoLabelTexto();
    const wb = XLSX.utils.book_new();

    const resumen = [
      [data.nombreNegocio || "Reporte", periodoLabel],
      [],
      ["Ventas del período", totalVentas],
      ["Gastos del período", totalGastos],
      ["Gastos sobre ingresos (%)", Number(gastosPctIngresos.toFixed(1))],
      [],
      ["Flujo Operativo", flujoOperativo],
      ["Flujo de Inversión", flujoInversion],
      ["Flujo de Financiamiento", flujoFinanciamiento],
      ["Saldo Global", saldoGlobal],
      [],
      ["Punto de equilibrio (aprox.)", puntoEquilibrio || "N/D"],
    ];
    XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(resumen), "Resumen");

    const filasMensual = flujoAnual.map((m) => [m.mes, m.Ventas, m.Gastos, m.Ventas - m.Gastos]);
    const totalAnualVentas = flujoAnual.reduce((a, m) => a + m.Ventas, 0);
    const totalAnualGastos = flujoAnual.reduce((a, m) => a + m.Gastos, 0);
    const detalleMensual = [
      [`Detalle mensual — ${year}`],
      ["Mes", "Ventas", "Gastos", "Resultado"],
      ...filasMensual,
      [],
      ["Total del año", totalAnualVentas, totalAnualGastos, totalAnualVentas - totalAnualGastos],
    ];
    XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(detalleMensual), "Detalle mensual");

    const hoja = (titulo, rows, cols) => {
      const aoa = [cols, ...rows.map((r) => cols.map((c) => r[c]))];
      XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(aoa), titulo.slice(0, 31));
    };
    hoja("Ventas por producto", porProducto.map((r) => ({ Producto: r.name, Total: r.value })), ["Producto", "Total"]);
    hoja("Ventas por familia", porFamilia.map((r) => ({ Familia: r.name, Total: r.value })), ["Familia", "Total"]);
    if (mostrarPorPunto) hoja("Ventas por punto venta", porPunto.map((r) => ({ "Punto de venta": r.name, Total: r.value })), ["Punto de venta", "Total"]);
    if (mostrarPorLista) hoja("Ventas por lista precio", porLista.map((r) => ({ Lista: r.name, Total: r.value })), ["Lista", "Total"]);
    hoja(
      "Gastos por rubro",
      porRubro.map((r) => ({ Rubro: r.name, Monto: r.value, "% de gastos": totalGastos ? Number(((r.value / totalGastos) * 100).toFixed(1)) : 0 })),
      ["Rubro", "Monto", "% de gastos"]
    );

    const prefijo = data.nombreNegocio ? data.nombreNegocio.replace(/[^a-zA-Z0-9]+/g, "_") + "_" : "";
    const sufijoArchivo = mode === "mensual" ? month : mode === "rango" ? `${rangoDesde}_a_${rangoHasta}` : year;
    XLSX.writeFile(wb, `reporte_${prefijo}${sufijoArchivo}.xlsx`);
  }

  return (
    <div className="flex flex-col gap-5">
      <div className="flex flex-wrap items-end justify-between gap-3">
        <div>
          <h1 style={{ fontSize: 21, fontWeight: 700, color: C.ink, margin: 0 }}>Indicadores</h1>
          <p style={{ fontSize: 13, color: C.inkSoft, margin: "2px 0 0" }}>Ventas, gastos y el flujo real de tu caja, siempre actualizado.</p>
        </div>
        <div className="flex gap-2 items-end flex-wrap">
          <Button variant="ghost" onClick={descargarReporte}>
            <Download size={15} /> Descargar reporte
          </Button>
          <Field label="Ver">
            <Select value={mode} onChange={(e) => setMode(e.target.value)}>
              <option value="mensual">Un mes</option>
              <option value="anual">Todo el año</option>
              <option value="rango">Rango personalizado</option>
            </Select>
          </Field>
          {mode === "mensual" && (
            <>
              <Field label="Año">
                <Select value={year} onChange={(e) => setYear(e.target.value)}>
                  {years.map((y) => <option key={y} value={y}>{y}</option>)}
                </Select>
              </Field>
              <Field label="Mes">
                <Select value={month} onChange={(e) => setMonth(e.target.value)}>
                  {MESES.map((m, i) => {
                    const key = `${year}-${String(i + 1).padStart(2, "0")}`;
                    return <option key={key} value={key}>{m}</option>;
                  })}
                </Select>
              </Field>
            </>
          )}
          {mode === "anual" && (
            <Field label="Año">
              <Select value={year} onChange={(e) => setYear(e.target.value)}>
                {years.map((y) => <option key={y} value={y}>{y}</option>)}
              </Select>
            </Field>
          )}
          {mode === "rango" && (
            <>
              <Field label="Desde">
                <TextInput type="date" value={rangoDesde} onChange={(e) => setRangoDesde(e.target.value)} />
              </Field>
              <Field label="Hasta">
                <TextInput type="date" value={rangoHasta} onChange={(e) => setRangoHasta(e.target.value)} />
              </Field>
            </>
          )}
        </div>
      </div>

      <div className="flex gap-4 flex-wrap">
        <KPI label="Ventas del período" value={money(totalVentas)} accent={C.green} delta={comparacion && deltaInfo(comparacion.ventas, false)} />
        <KPI label="Ticket promedio" value={money(ticketPromedio)} accent={C.green} />
        <KPI label="Gastos del período" value={money(totalGastos)} accent={C.rust} delta={comparacion && deltaInfo(comparacion.gastos, true)} />
        <KPI label="Gastos sobre ingresos" value={pct(gastosPctIngresos)} accent={C.gold} />
        <KPI label="Por cobrar" value={money(porCobrar)} accent={C.gold} />
        <KPI label="Punto de equilibrio (aprox.)" value={puntoEquilibrio != null ? money(puntoEquilibrio) : "N/D"} accent={C.ink} />
      </div>

      <Card style={{ padding: 18 }}>
        <div style={{ fontSize: 14, fontWeight: 600, marginBottom: 12 }}>Ingresos por ventas</div>
        <div className="flex gap-4 flex-wrap">
          <KPI label="Ingresos por ventas (bruto)" value={money(totalVentasBruto)} accent={C.ink} />
          <KPI label="Descuentos aplicados" value={money(totalDescuentos)} accent={C.rust} />
          <KPI label="Ingreso neto" value={money(totalVentas)} accent={C.green} />
        </div>
      </Card>

      <Card style={{ padding: 18 }}>
        <div style={{ fontSize: 14, fontWeight: 600, marginBottom: 12 }}>Flujo de fondos del período</div>
        <div className="flex gap-4 flex-wrap">
          <KPI label="Flujo Operativo" value={money(flujoOperativo)} accent={flujoOperativo >= 0 ? C.green : C.rust} delta={comparacion && deltaInfo(comparacion.operativo, false)} />
          <KPI label="Flujo de Inversión" value={money(flujoInversion)} accent={flujoInversion >= 0 ? C.green : C.rust} />
          <KPI label="Flujo de Financiamiento" value={money(flujoFinanciamiento)} accent={flujoFinanciamiento >= 0 ? C.green : C.rust} />
          <KPI label="Saldo Global" value={money(saldoGlobal)} accent={saldoGlobal >= 0 ? C.greenDark : C.rust} />
        </div>
        <div style={{ fontSize: 12, color: C.inkFaint, marginTop: 10 }}>
          El Saldo Global es la suma de los tres flujos y debería coincidir con la variación de tu Arqueo de Caja en el mismo período.
          El Flujo Operativo ya descuenta lo que todavía no se cobró (tarjetas/pasarelas pendientes) y las comisiones confirmadas — refleja la plata que realmente entró, no lo vendido en bruto.
          {puntoEquilibrio != null && <> · Margen de contribución estimado: {pct(margenContribucionPct)}</>}
        </div>
      </Card>

      <Card style={{ padding: 18 }}>
        <div className="flex items-center justify-between flex-wrap gap-2" style={{ marginBottom: 4 }}>
          <div style={{ fontSize: 14, fontWeight: 600, color: C.ink }}>Ventas vs. Gastos por mes — {year}</div>
          <div className="flex gap-1">
            <Button variant={chartType === "bar" ? "primary" : "ghost"} style={{ padding: "4px 10px", fontSize: 12 }} onClick={() => setChartType("bar")}>Columnas</Button>
            <Button variant={chartType === "line" ? "primary" : "ghost"} style={{ padding: "4px 10px", fontSize: 12 }} onClick={() => setChartType("line")}>Líneas</Button>
          </div>
        </div>
        <div style={{ fontSize: 11.5, color: C.inkFaint, marginBottom: 8 }}>
          Dato mensual fijo — no cambia con el rango o mes que elijas arriba, siempre muestra el año completo como referencia.
        </div>
        <ResponsiveContainer width="100%" height={230}>
          {chartType === "bar" ? (
            <BarChart data={flujoAnual}>
              <CartesianGrid strokeDasharray="3 3" stroke={C.line} vertical={false} />
              <XAxis dataKey="mes" tick={{ fontSize: 12, fill: C.inkSoft }} axisLine={{ stroke: C.line }} tickLine={false} />
              <YAxis tick={{ fontSize: 11, fill: C.inkSoft }} axisLine={false} tickLine={false} tickFormatter={(v) => money(v)} width={70} />
              <Tooltip formatter={(v) => money(v)} contentStyle={{ borderRadius: 8, border: `1px solid ${C.line}`, fontSize: 13 }} />
              <Legend wrapperStyle={{ fontSize: 13 }} />
              <Bar dataKey="Ventas" fill={C.green} radius={[3, 3, 0, 0]} />
              <Bar dataKey="Gastos" fill={C.rust} radius={[3, 3, 0, 0]} />
            </BarChart>
          ) : (
            <LineChart data={flujoAnual}>
              <CartesianGrid strokeDasharray="3 3" stroke={C.line} vertical={false} />
              <XAxis dataKey="mes" tick={{ fontSize: 12, fill: C.inkSoft }} axisLine={{ stroke: C.line }} tickLine={false} />
              <YAxis tick={{ fontSize: 11, fill: C.inkSoft }} axisLine={false} tickLine={false} tickFormatter={(v) => money(v)} width={70} />
              <Tooltip formatter={(v) => money(v)} contentStyle={{ borderRadius: 8, border: `1px solid ${C.line}`, fontSize: 13 }} />
              <Legend wrapperStyle={{ fontSize: 13 }} />
              <Line type="monotone" dataKey="Ventas" stroke={C.green} strokeWidth={2.5} dot={{ r: 3 }} />
              <Line type="monotone" dataKey="Gastos" stroke={C.rust} strokeWidth={2.5} dot={{ r: 3 }} />
            </LineChart>
          )}
        </ResponsiveContainer>
      </Card>

      <div className="flex flex-col gap-3">
        <AccordionItem title="Ventas por producto ($)" defaultOpen>
          {porProducto.length === 0 ? <Empty /> : (
            <ResponsiveContainer width="100%" height={240}>
              <BarChart data={porProducto} layout="vertical" margin={{ left: 10 }}>
                <XAxis type="number" hide />
                <YAxis type="category" dataKey="name" width={110} tick={{ fontSize: 12, fill: C.ink }} axisLine={false} tickLine={false} />
                <Tooltip formatter={(v) => money(v)} />
                <Bar dataKey="value" fill={C.green} radius={[0, 4, 4, 0]} />
              </BarChart>
            </ResponsiveContainer>
          )}
        </AccordionItem>

        <AccordionItem title="Ventas por producto (unidades)">
          {porProductoCant.length === 0 ? <Empty /> : (
            <ResponsiveContainer width="100%" height={240}>
              <BarChart data={porProductoCant} layout="vertical" margin={{ left: 10 }}>
                <XAxis type="number" hide />
                <YAxis type="category" dataKey="name" width={110} tick={{ fontSize: 12, fill: C.ink }} axisLine={false} tickLine={false} />
                <Tooltip />
                <Bar dataKey="value" fill={C.gold} radius={[0, 4, 4, 0]} />
              </BarChart>
            </ResponsiveContainer>
          )}
        </AccordionItem>

        <AccordionItem title="Ventas por familia de producto">
          {porFamilia.length === 0 ? <Empty /> : <DonutChart data={porFamilia} />}
        </AccordionItem>

        {mostrarPorLista && (
          <AccordionItem title="Ventas por tipo de cliente (lista de precio)">
            {porLista.length === 0 ? <Empty /> : <DonutChart data={porLista} />}
          </AccordionItem>
        )}

        {mostrarPorPunto && (
          <AccordionItem title="Ventas por punto de venta ($)">
            {porPunto.length === 0 ? <Empty /> : (
              <ResponsiveContainer width="100%" height={220}>
                <BarChart data={porPunto}>
                  <XAxis dataKey="name" tick={{ fontSize: 12, fill: C.inkSoft }} axisLine={{ stroke: C.line }} tickLine={false} />
                  <YAxis tick={{ fontSize: 11, fill: C.inkSoft }} axisLine={false} tickLine={false} tickFormatter={(v) => money(v)} width={65} />
                  <Tooltip formatter={(v) => money(v)} />
                  <Bar dataKey="value" fill={C.green} radius={[3, 3, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            )}
          </AccordionItem>
        )}

        <AccordionItem title="Gastos por rubro" defaultOpen>
          {porRubro.length === 0 ? <Empty /> : (
            <table style={{ width: "100%", fontSize: 13, borderCollapse: "collapse" }}>
              <thead>
                <tr style={{ color: C.inkSoft, textAlign: "left" }}>
                  <th style={{ paddingBottom: 6 }}>Rubro</th>
                  <th style={{ paddingBottom: 6, textAlign: "right" }}>Monto</th>
                  <th style={{ paddingBottom: 6, textAlign: "right" }}>% de gastos</th>
                </tr>
              </thead>
              <tbody>
                {porRubro.map((r) => (
                  <tr key={r.name} style={{ borderTop: `1px solid ${C.line}` }}>
                    <td style={{ padding: "6px 0" }}>{r.name}</td>
                    <td style={{ padding: "6px 0", textAlign: "right", fontVariantNumeric: "tabular-nums" }}>{money(r.value)}</td>
                    <td style={{ padding: "6px 0", textAlign: "right", color: C.inkSoft }}>{pct(totalGastos ? (r.value / totalGastos) * 100 : 0)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </AccordionItem>
      </div>
    </div>
  );
}
function Empty() {
  return <div style={{ fontSize: 13, color: C.inkFaint, padding: "30px 0", textAlign: "center" }}>Sin datos todavía para este período.</div>;
}
function DonutChart({ data }) {
  return (
    <ResponsiveContainer width="100%" height={220}>
      <PieChart>
        <Pie data={data} dataKey="value" nameKey="name" innerRadius={45} outerRadius={75} paddingAngle={2}>
          {data.map((_, i) => (
            <Cell key={i} fill={CHART_COLORS[i % CHART_COLORS.length]} />
          ))}
        </Pie>
        <Legend wrapperStyle={{ fontSize: 12 }} />
        <Tooltip formatter={(v) => money(v)} />
      </PieChart>
    </ResponsiveContainer>
  );
}

/* ---------- Ventas ---------- */
function VentasView({ data, update }) {
  const listaLabels = data.listaLabels || LISTA_LABEL_DEFAULT;
  const combinable = !!data.permitirCombinarDescuentos;
  const codigosActivos = (data.codigosDescuento || []).filter((c) => c.activo && (!c.vencimiento || c.vencimiento >= todayStr()));
  const hayCodigos = codigosActivos.length > 0;
  const [pendingDelete, setPendingDelete] = useState(null);

  const [carrito, setCarrito] = useState([]);
  const [item, setItem] = useState({ productoTexto: "", cantidad: 1, lista: LISTA_KEYS[0], precioUnitario: 0 });
  const [orden, setOrden] = useState({
    fecha: todayStr(),
    puntoVenta: data.puntosVenta[0] || "",
    medioPago: data.medios[0] || "",
    observaciones: "",
    descuentoManual: 0,
    codigoDescuentoId: "",
    clienteId: "",
  });
  const [verObs, setVerObs] = useState(false);
  const [verHistorico, setVerHistorico] = useState(false);
  const [verFecha, setVerFecha] = useState(false);
  const [localError, setLocalError] = useState("");
  const [justSaved, setJustSaved] = useState(false);

  const textoBusqueda = item.productoTexto.trim().toLowerCase();
  const productoItem = data.productos.find(
    (p) => (p.codigo && p.codigo.trim().toLowerCase() === textoBusqueda) || p.nombre.trim().toLowerCase() === textoBusqueda
  );
  const esCtaCte = orden.medioPago === MEDIO_CTA_CTE;
  const codigoSeleccionado = codigosActivos.find((c) => c.id === orden.codigoDescuentoId);
  const descuentoPct = (Number(orden.descuentoManual) || 0) + (codigoSeleccionado ? Number(codigoSeleccionado.porcentaje) || 0 : 0);

  useEffect(() => {
    if (productoItem) {
      const campo = LISTA_CAMPO[item.lista];
      setItem((f) => ({ ...f, precioUnitario: productoItem[campo] || 0 }));
    }
  }, [item.productoTexto, item.lista]); // eslint-disable-line

  function agregarItem() {
    if (!productoItem) return;
    const cantidad = Number(item.cantidad) || 0;
    const precioUnitario = Number(item.precioUnitario) || 0;
    if (!cantidad) return;
    setCarrito([
      ...carrito,
      {
        tempId: uid(),
        productoId: productoItem.id,
        productoNombre: productoItem.nombre,
        familia: productoItem.familia,
        cantidad,
        lista: item.lista,
        listaLabel: listaLabels[item.lista] || LISTA_LABEL_DEFAULT[item.lista],
        precioUnitario,
        subtotal: cantidad * precioUnitario,
      },
    ]);
    setItem((f) => ({ ...f, productoTexto: "", cantidad: 1 }));
  }
  function quitarItem(tempId) {
    setCarrito(carrito.filter((it) => it.tempId !== tempId));
  }

  const totalBrutoCarrito = carrito.reduce((a, it) => a + it.subtotal, 0);
  const pctFinal = Math.min(descuentoPct, 100);
  const descuentoMontoTotal = totalBrutoCarrito * (pctFinal / 100);
  const totalNetoCarrito = totalBrutoCarrito - descuentoMontoTotal;

  function confirmarVenta() {
    setLocalError("");
    try {
      if (carrito.length === 0) { setLocalError("Agregá al menos un producto antes de registrar."); return; }
      if (esCtaCte && !orden.clienteId) { setLocalError("Elegí un cliente para una venta a Cuenta Corriente."); return; }
      const ventaId = uid();
      const cliente = esCtaCte ? (data.clientes || []).find((c) => c.id === orden.clienteId) : null;
      const config = (data.medioConfig || {})[orden.medioPago] || {};
      const diasAcreditacion = esCtaCte ? null : Number(config.diasAcreditacion) || 0;
      const comisionPctEstimada = esCtaCte ? 0 : Number(config.comisionPct) || 0;
      const fechaEstimadaAcreditacion = esCtaCte ? null : sumarDias(orden.fecha, diasAcreditacion);
      const estadoCobro = esCtaCte ? undefined : diasAcreditacion > 0 ? "pendiente" : "acreditado";

      const nuevasVentas = carrito.map((it) => {
        const itemDescuento = totalBrutoCarrito ? (it.subtotal / totalBrutoCarrito) * descuentoMontoTotal : 0;
        return {
          id: uid(),
          ventaId,
          fecha: orden.fecha,
          productoId: it.productoId,
          productoNombre: it.productoNombre,
          familia: it.familia,
          cantidad: it.cantidad,
          puntoVenta: orden.puntoVenta,
          lista: it.lista,
          listaLabel: it.listaLabel,
          precioUnitario: it.precioUnitario,
          totalBruto: it.subtotal,
          descuentoPct: pctFinal,
          descuentoMonto: itemDescuento,
          total: it.subtotal - itemDescuento,
          medioPago: orden.medioPago,
          observaciones: orden.observaciones,
          clienteId: cliente ? cliente.id : undefined,
          clienteNombre: cliente ? cliente.nombre : undefined,
          diasAcreditacion,
          comisionPctEstimada,
          fechaEstimadaAcreditacion,
          estadoCobro,
          confirmado: false,
        };
      });

      let productos = data.productos;
      const movStock = [...data.movStock];
      carrito.forEach((it) => {
        productos = productos.map((p) => (p.id === it.productoId ? { ...p, stock: Number(p.stock || 0) - it.cantidad } : p));
        movStock.push({ id: uid(), fecha: orden.fecha, productoId: it.productoId, cantidad: -it.cantidad, tipo: "venta" });
      });

      update({ ...data, ventas: [...nuevasVentas, ...data.ventas], productos, movStock });
      setCarrito([]);
      setOrden((f) => ({ ...f, observaciones: "", descuentoManual: 0, codigoDescuentoId: "", clienteId: "" }));
      setVerObs(false);
      setJustSaved(true);
      setTimeout(() => setJustSaved(false), 2500);
    } catch (err) {
      setLocalError("Error: " + (err?.message || String(err)));
    }
  }

  function eliminar(v) {
    const productos = data.productos.map((p) =>
      p.id === v.productoId ? { ...p, stock: Number(p.stock || 0) + v.cantidad } : p
    );
    update({ ...data, ventas: data.ventas.filter((x) => x.id !== v.id), productos });
  }

  return (
    <div className="flex flex-col gap-5">
      <div>
        <h1 style={{ fontSize: 21, fontWeight: 700, color: C.ink, margin: 0 }}>Ventas</h1>
        <p style={{ fontSize: 13, color: C.inkSoft, margin: "2px 0 0" }}>Agregá uno o varios productos, y después cerrá la venta.</p>
      </div>

      <Card style={{ padding: 18 }}>
        <div style={{ fontSize: 13.5, fontWeight: 600, marginBottom: 10 }}>1. Agregar productos</div>
        <div className="flex flex-wrap gap-3 items-end">
          <Field label="Producto">
            <TextInput
              list="lista-productos"
              value={item.productoTexto}
              onChange={(e) => setItem({ ...item, productoTexto: e.target.value })}
              placeholder="Escribí para buscar..."
              style={{ minWidth: 180 }}
            />
            <datalist id="lista-productos">
              {data.productos.map((p) => <option key={p.id} value={p.nombre} />)}
              {data.productos.filter((p) => p.codigo).map((p) => <option key={p.id + "-cod"} value={p.codigo} />)}
            </datalist>
          </Field>
          <Field label="Cantidad">
            <TextInput type="number" min="1" value={item.cantidad} onChange={(e) => setItem({ ...item, cantidad: e.target.value })} style={{ width: 80 }} />
          </Field>
          <Field label="Lista de precio">
            <Select value={item.lista} onChange={(e) => setItem({ ...item, lista: e.target.value })}>
              {LISTA_KEYS.map((k) => <option key={k} value={k}>{listaLabels[k] || LISTA_LABEL_DEFAULT[k]}</option>)}
            </Select>
          </Field>
          <Field label="Precio unitario">
            <MoneyField value={item.precioUnitario} onChange={(v) => setItem({ ...item, precioUnitario: v })} style={{ width: 110 }} placeholder="0" />
          </Field>
          <Button type="button" onClick={agregarItem} disabled={!productoItem}>
            <Plus size={15} /> Agregar a la venta
          </Button>
        </div>

        {carrito.length > 0 && (
          <div style={{ marginTop: 16 }}>
            <table style={{ width: "100%", fontSize: 13, borderCollapse: "collapse" }}>
              <thead>
                <tr style={{ color: C.inkSoft, textAlign: "left" }}>
                  <th style={{ padding: "6px 8px" }}>Producto</th>
                  <th style={{ padding: "6px 8px" }}>Cant.</th>
                  <th style={{ padding: "6px 8px" }}>Lista</th>
                  <th style={{ padding: "6px 8px", textAlign: "right" }}>P. Unit.</th>
                  <th style={{ padding: "6px 8px", textAlign: "right" }}>Subtotal</th>
                  <th></th>
                </tr>
              </thead>
              <tbody>
                {carrito.map((it) => (
                  <tr key={it.tempId} style={{ borderTop: `1px solid ${C.line}` }}>
                    <td style={{ padding: "6px 8px" }}>{it.productoNombre}</td>
                    <td style={{ padding: "6px 8px" }}>{it.cantidad}</td>
                    <td style={{ padding: "6px 8px" }}>{it.listaLabel}</td>
                    <td style={{ padding: "6px 8px", textAlign: "right" }}>{money(it.precioUnitario)}</td>
                    <td style={{ padding: "6px 8px", textAlign: "right", fontWeight: 600 }}>{money(it.subtotal)}</td>
                    <td style={{ padding: "6px 8px" }}>
                      <Trash2 size={14} style={{ cursor: "pointer", color: C.inkFaint }} onClick={() => quitarItem(it.tempId)} />
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </Card>

      {carrito.length > 0 && (
        <Card style={{ padding: 18 }}>
          <div style={{ fontSize: 13.5, fontWeight: 600, marginBottom: 10 }}>2. Cerrar la venta</div>
          <div className="flex flex-wrap gap-3 items-end">
            <Field label="Descuento %">
              <TextInput
                type="number"
                value={orden.descuentoManual}
                onChange={(e) => setOrden({ ...orden, descuentoManual: e.target.value, codigoDescuentoId: combinable ? orden.codigoDescuentoId : "" })}
                disabled={!combinable && !!orden.codigoDescuentoId}
                style={{ width: 80 }}
              />
            </Field>
            {hayCodigos && (
              <Field label="Código de descuento">
                <Select
                  value={orden.codigoDescuentoId}
                  onChange={(e) => setOrden({ ...orden, codigoDescuentoId: e.target.value, descuentoManual: combinable ? orden.descuentoManual : 0 })}
                  disabled={!combinable && Number(orden.descuentoManual) > 0}
                  style={{ minWidth: 140 }}
                >
                  <option value="">Ninguno</option>
                  {codigosActivos.map((c) => <option key={c.id} value={c.id}>{c.codigo} (-{c.porcentaje}%)</option>)}
                </Select>
              </Field>
            )}
            <Field label="Punto de venta">
              <Select value={orden.puntoVenta} onChange={(e) => setOrden({ ...orden, puntoVenta: e.target.value })}>
                {data.puntosVenta.map((pv) => <option key={pv} value={pv}>{pv}</option>)}
              </Select>
            </Field>
            <Field label="Medio de pago">
              <Select value={orden.medioPago} onChange={(e) => setOrden({ ...orden, medioPago: e.target.value })}>
                {data.medios.map((m) => <option key={m} value={m}>{m}</option>)}
              </Select>
            </Field>
            {esCtaCte && (
              <Field label="Cliente">
                <Select value={orden.clienteId} onChange={(e) => setOrden({ ...orden, clienteId: e.target.value })} required style={{ minWidth: 150 }}>
                  <option value="">Elegir...</option>
                  {(data.clientes || []).map((c) => <option key={c.id} value={c.id}>{c.nombre}</option>)}
                </Select>
              </Field>
            )}
            <Button variant="ghost" type="button" onClick={() => setVerFecha(!verFecha)}>
              {verFecha ? `Fecha: ${orden.fecha}` : "Cargar venta de otro día"}
            </Button>
            <Button variant="ghost" type="button" onClick={() => setVerObs(!verObs)}>
              <MessageSquarePlus size={15} /> Observaciones
            </Button>
          </div>
          {verFecha && (
            <div style={{ marginTop: 10 }}>
              <Field label="Fecha de la venta">
                <TextInput type="date" value={orden.fecha} onChange={(e) => setOrden({ ...orden, fecha: e.target.value })} style={{ width: 170 }} />
              </Field>
            </div>
          )}
          {verObs && (
            <div style={{ marginTop: 10 }}>
              <Field label="Observaciones (opcional)">
                <TextInput
                  value={orden.observaciones}
                  onChange={(e) => setOrden({ ...orden, observaciones: e.target.value })}
                  placeholder="Cualquier aclaración sobre esta venta"
                  style={{ width: "100%" }}
                />
              </Field>
            </div>
          )}
          <div
            className="flex items-center justify-between flex-wrap gap-3"
            style={{ marginTop: 16, paddingTop: 16, borderTop: `1px solid ${C.line}` }}
          >
            <div style={{ fontSize: 12.5, color: C.inkSoft }}>
              Bruto: <strong>{money(totalBrutoCarrito)}</strong>
              {descuentoPct > 0 && <> · Descuento ({pct(descuentoPct)}): <strong style={{ color: C.rust }}>-{money(descuentoMontoTotal)}</strong></>}
              {!verFecha && <> · {orden.fecha}</>}
            </div>
            <div className="flex items-center gap-4">
              <div style={{ textAlign: "right" }}>
                <div style={{ fontSize: 11.5, color: C.inkSoft, textTransform: "uppercase", letterSpacing: 0.5 }}>Total</div>
                <div style={{ fontSize: 30, fontWeight: 700, color: C.green, lineHeight: 1.1 }}>{money(totalNetoCarrito)}</div>
              </div>
              <Button type="button" onClick={confirmarVenta} disabled={esCtaCte && !orden.clienteId} style={{ padding: "12px 22px", fontSize: 15 }}>
                <Check size={17} /> Registrar venta
              </Button>
            </div>
          </div>
          {localError && <div style={{ marginTop: 10, fontSize: 13, color: C.rust, fontWeight: 600 }}>{localError}</div>}
          {justSaved && <div style={{ marginTop: 10, fontSize: 13, color: C.green, fontWeight: 600 }}>✓ Venta registrada</div>}
        </Card>
      )}

      <div>
        <Button variant="ghost" onClick={() => setVerHistorico(!verHistorico)}>
          {verHistorico ? "Ocultar ventas históricas" : "Ver ventas históricas"}
        </Button>
      </div>

      {verHistorico && (
        <Card style={{ padding: 0, overflow: "hidden" }}>
          <table style={{ width: "100%", fontSize: 13, borderCollapse: "collapse" }}>
            <thead>
              <tr style={{ background: C.bg, textAlign: "left", color: C.inkSoft }}>
                {["Fecha", "Producto", "Cant.", "Lista", "Bruto", "Desc.", "Total", "Punto de venta", "Medio", "Cobro", "Cliente", "Obs.", ""].map((h) => (
                  <th key={h} style={{ padding: "10px 12px", fontWeight: 600 }}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {[...data.ventas].sort((a, b) => (a.fecha < b.fecha ? 1 : a.fecha > b.fecha ? -1 : 0)).map((v) => (
                <tr key={v.id} style={{ borderTop: `1px solid ${C.line}` }}>
                  <td style={{ padding: "8px 12px" }}>{v.fecha}</td>
                  <td style={{ padding: "8px 12px" }}>{v.productoNombre}</td>
                  <td style={{ padding: "8px 12px" }}>{v.cantidad}</td>
                  <td style={{ padding: "8px 12px" }}>{v.listaLabel || v.lista}</td>
                  <td style={{ padding: "8px 12px" }}>{money(v.totalBruto ?? v.total)}</td>
                  <td style={{ padding: "8px 12px", color: C.rust }}>{v.descuentoMonto ? `-${money(v.descuentoMonto)}` : "—"}</td>
                  <td style={{ padding: "8px 12px", fontWeight: 600 }}>{money(v.total)}</td>
                  <td style={{ padding: "8px 12px" }}>{v.puntoVenta}</td>
                  <td style={{ padding: "8px 12px" }}>{v.medioPago}</td>
                  <td style={{ padding: "8px 12px" }}>
                    {v.medioPago === MEDIO_CTA_CTE ? (
                      <span style={{ color: C.inkFaint }}>Cta. Cte.</span>
                    ) : v.estadoCobro === "pendiente" && !v.confirmado ? (
                      <span style={{ color: estaAcreditadaVenta(v) ? C.gold : C.rust, fontWeight: 600 }}>
                        {estaAcreditadaVenta(v) ? "Estimado ✓" : "Pendiente"}
                      </span>
                    ) : (
                      <span style={{ color: C.green, fontWeight: 600 }}>
                        Acreditado{v.comisionMonto ? ` (com. ${money(v.comisionMonto)})` : ""}
                      </span>
                    )}
                  </td>
                  <td style={{ padding: "8px 12px" }}>{v.clienteNombre || "—"}</td>
                  <td style={{ padding: "8px 12px", color: C.inkSoft, maxWidth: 160 }}>{v.observaciones}</td>
                  <td style={{ padding: "8px 12px" }}>
                    <Trash2 size={15} style={{ cursor: "pointer", color: C.inkFaint }} onClick={() => setPendingDelete(v)} />
                  </td>
                </tr>
              ))}
              {data.ventas.length === 0 && (
                <tr><td colSpan={13} style={{ padding: 24, textAlign: "center", color: C.inkFaint }}>Todavía no cargaste ninguna venta.</td></tr>
              )}
            </tbody>
          </table>
        </Card>
      )}
      {pendingDelete && (
        <ConfirmDialog
          mensaje={`¿Seguro que querés eliminar esta venta (${pendingDelete.productoNombre}, ${money(pendingDelete.total)}, ${pendingDelete.fecha})? No se puede deshacer.`}
          onConfirmar={() => { eliminar(pendingDelete); setPendingDelete(null); }}
          onCancelar={() => setPendingDelete(null)}
        />
      )}
    </div>
  );
}

/* ---------- Gastos ---------- */
function GastosView({ data, update }) {
  const [form, setForm] = useState({ fecha: todayStr(), rubro: data.rubros[0] || "", monto: "", detalle: "", medioPago: data.medios[0] || "", observaciones: "" });
  const [verObs, setVerObs] = useState(false);
  const [verHistorico, setVerHistorico] = useState(false);
  const [localError, setLocalError] = useState("");
  const [justSaved, setJustSaved] = useState(false);
  const [pendingDelete, setPendingDelete] = useState(null);

  function submit() {
    setLocalError("");
    try {
      const monto = Number(form.monto) || 0;
      if (!monto) { setLocalError("Falta indicar un monto mayor a cero."); return; }
      const gasto = { id: uid(), ...form, monto };
      update({ ...data, gastos: [gasto, ...data.gastos] });
      setForm({ fecha: todayStr(), rubro: data.rubros[0] || "", monto: "", detalle: "", medioPago: data.medios[0] || "", observaciones: "" });
      setVerObs(false);
      setJustSaved(true);
      setTimeout(() => setJustSaved(false), 2500);
    } catch (err) {
      setLocalError("Error: " + (err?.message || String(err)));
    }
  }
  function eliminar(id) {
    update({ ...data, gastos: data.gastos.filter((g) => g.id !== id) });
  }
  const gastosOrdenados = [...data.gastos].sort((a, b) => (a.fecha < b.fecha ? 1 : a.fecha > b.fecha ? -1 : 0));

  return (
    <div className="flex flex-col gap-5">
      <div>
        <h1 style={{ fontSize: 21, fontWeight: 700, color: C.ink, margin: 0 }}>Gastos</h1>
        <p style={{ fontSize: 13, color: C.inkSoft, margin: "2px 0 0" }}>Registrá cada gasto con su rubro para ver el % sobre el total.</p>
      </div>

      <Card style={{ padding: 18 }}>
        <div className="flex flex-wrap gap-3 items-end">
          <Field label="Fecha">
            <TextInput type="date" value={form.fecha} onChange={(e) => setForm({ ...form, fecha: e.target.value })} required />
          </Field>
          <Field label="Rubro">
            <Select value={form.rubro} onChange={(e) => setForm({ ...form, rubro: e.target.value })}>
              {data.rubros.map((r) => <option key={r} value={r}>{r}</option>)}
            </Select>
          </Field>
          <Field label="Detalle">
            <TextInput value={form.detalle} onChange={(e) => setForm({ ...form, detalle: e.target.value })} placeholder="Opcional" />
          </Field>
          <Field label="Monto">
            <MoneyField value={form.monto} onChange={(v) => setForm({ ...form, monto: v })} style={{ width: 110 }} placeholder="0" />
          </Field>
          <Field label="Medio de pago">
            <Select value={form.medioPago} onChange={(e) => setForm({ ...form, medioPago: e.target.value })}>
              {data.medios.map((m) => <option key={m} value={m}>{m}</option>)}
            </Select>
          </Field>
          <Button variant="ghost" type="button" onClick={() => setVerObs(!verObs)}>
            <MessageSquarePlus size={15} /> Observaciones
          </Button>
          <Button type="button" onClick={submit}><Plus size={15} /> Registrar gasto</Button>
        </div>
        {localError && <div style={{ marginTop: 10, fontSize: 13, color: C.rust, fontWeight: 600 }}>{localError}</div>}
        {justSaved && <div style={{ marginTop: 10, fontSize: 13, color: C.green, fontWeight: 600 }}>✓ Gasto registrado</div>}
        {verObs && (
          <div style={{ marginTop: 10 }}>
            <Field label="Observaciones (opcional)">
              <TextInput
                value={form.observaciones}
                onChange={(e) => setForm({ ...form, observaciones: e.target.value })}
                placeholder="Cualquier aclaración sobre este gasto"
                style={{ width: "100%" }}
              />
            </Field>
          </div>
        )}
      </Card>

      <div>
        <Button variant="ghost" onClick={() => setVerHistorico(!verHistorico)}>
          {verHistorico ? "Ocultar gastos históricos" : "Ver gastos históricos"}
        </Button>
      </div>

      {verHistorico && (
        <Card style={{ padding: 0, overflow: "hidden" }}>
          <table style={{ width: "100%", fontSize: 13, borderCollapse: "collapse" }}>
            <thead>
              <tr style={{ background: C.bg, textAlign: "left", color: C.inkSoft }}>
                {["Fecha", "Rubro", "Detalle", "Monto", "Medio", "Obs.", ""].map((h) => (
                  <th key={h} style={{ padding: "10px 12px", fontWeight: 600 }}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {gastosOrdenados.map((g) => (
                <tr key={g.id} style={{ borderTop: `1px solid ${C.line}` }}>
                  <td style={{ padding: "8px 12px" }}>{g.fecha}</td>
                  <td style={{ padding: "8px 12px" }}>{g.rubro}</td>
                  <td style={{ padding: "8px 12px", color: C.inkSoft }}>{g.detalle}</td>
                  <td style={{ padding: "8px 12px", fontWeight: 600 }}>{money(g.monto)}</td>
                  <td style={{ padding: "8px 12px" }}>{g.medioPago}</td>
                  <td style={{ padding: "8px 12px", color: C.inkSoft }}>{g.observaciones}</td>
                  <td style={{ padding: "8px 12px" }}>
                    <Trash2 size={15} style={{ cursor: "pointer", color: C.inkFaint }} onClick={() => setPendingDelete(g)} />
                  </td>
                </tr>
              ))}
              {gastosOrdenados.length === 0 && (
                <tr><td colSpan={7} style={{ padding: 24, textAlign: "center", color: C.inkFaint }}>Todavía no cargaste ningún gasto.</td></tr>
              )}
            </tbody>
          </table>
        </Card>
      )}
      {pendingDelete && (
        <ConfirmDialog
          mensaje={`¿Seguro que querés eliminar este gasto (${pendingDelete.detalle || pendingDelete.rubro}, ${money(pendingDelete.monto)}, ${pendingDelete.fecha})? No se puede deshacer.`}
          onConfirmar={() => { eliminar(pendingDelete.id); setPendingDelete(null); }}
          onCancelar={() => setPendingDelete(null)}
        />
      )}
    </div>
  );
}

/* ---------- Productos y Stock ---------- */
function ProductosView({ data, update }) {
  const [nuevo, setNuevo] = useState(null);
  const [cargaStockId, setCargaStockId] = useState(null);
  const [cargaForm, setCargaForm] = useState({ cantidad: "", motivo: "Compra", fecha: todayStr() });

  function crearProducto() {
    setNuevo({ nombre: "", codigo: "", familia: data.familias[0] || "", precioMinorista: 0, precioMayorista: 0, precioOtro: 0, stock: 0, stockMinimo: "" });
  }
  function guardarNuevo() {
    if (!nuevo.nombre.trim()) return;
    update({ ...data, productos: [...data.productos, { id: uid(), ...nuevo }] });
    setNuevo(null);
  }
  function actualizarProducto(id, campo, valor) {
    update({ ...data, productos: data.productos.map((p) => (p.id === id ? { ...p, [campo]: valor } : p)) });
  }
  function eliminarProducto(id) {
    update({ ...data, productos: data.productos.filter((p) => p.id !== id) });
  }
  function confirmarCarga(producto) {
    const cant = Number(cargaForm.cantidad) || 0;
    if (!cant) return;
    const productos = data.productos.map((p) => (p.id === producto.id ? { ...p, stock: Number(p.stock || 0) + cant } : p));
    const movStock = [...data.movStock, { id: uid(), fecha: cargaForm.fecha, productoId: producto.id, cantidad: cant, tipo: "carga", motivo: cargaForm.motivo }];
    update({ ...data, productos, movStock });
    setCargaStockId(null);
    setCargaForm({ cantidad: "", motivo: "Compra", fecha: todayStr() });
  }

  return (
    <div className="flex flex-col gap-5">
      <div className="flex items-center justify-between">
        <div>
          <h1 style={{ fontSize: 21, fontWeight: 700, color: C.ink, margin: 0 }}>Productos y Stock</h1>
        </div>
        <Button onClick={crearProducto}><Plus size={15} /> Nuevo producto</Button>
      </div>

      {nuevo && (
        <Card style={{ padding: 18 }}>
          <div className="flex flex-wrap gap-3 items-end">
            <Field label="Nombre">
              <TextInput value={nuevo.nombre} onChange={(e) => setNuevo({ ...nuevo, nombre: e.target.value })} autoFocus />
            </Field>
            <Field label="Código (SKU, opcional)">
              <TextInput value={nuevo.codigo} onChange={(e) => setNuevo({ ...nuevo, codigo: e.target.value })} style={{ width: 110 }} placeholder="Si no usás código, dejalo vacío" />
            </Field>
            <Field label="Familia">
              <Select value={nuevo.familia} onChange={(e) => setNuevo({ ...nuevo, familia: e.target.value })}>
                {data.familias.map((f) => <option key={f} value={f}>{f}</option>)}
              </Select>
            </Field>
            <Field label={`P. ${data.listaLabels?.minorista || "Minorista"}`}>
              <TextInput type="number" value={nuevo.precioMinorista} onChange={(e) => setNuevo({ ...nuevo, precioMinorista: e.target.value })} style={{ width: 100 }} />
            </Field>
            <Field label={`P. ${data.listaLabels?.mayorista || "Mayorista"}`}>
              <TextInput type="number" value={nuevo.precioMayorista} onChange={(e) => setNuevo({ ...nuevo, precioMayorista: e.target.value })} style={{ width: 100 }} />
            </Field>
            <Field label={data.listaLabels?.otro || "Otro precio"}>
              <TextInput type="number" value={nuevo.precioOtro} onChange={(e) => setNuevo({ ...nuevo, precioOtro: e.target.value })} style={{ width: 100 }} />
            </Field>
            <Field label="Stock inicial">
              <TextInput type="number" value={nuevo.stock} onChange={(e) => setNuevo({ ...nuevo, stock: e.target.value })} style={{ width: 90 }} />
            </Field>
            <Field label="Stock mínimo (opcional)">
              <TextInput type="number" value={nuevo.stockMinimo} onChange={(e) => setNuevo({ ...nuevo, stockMinimo: e.target.value })} style={{ width: 90 }} />
            </Field>
            <Button onClick={guardarNuevo}><Check size={15} /> Guardar</Button>
            <Button variant="ghost" onClick={() => setNuevo(null)}>Cancelar</Button>
          </div>
        </Card>
      )}

      <Card style={{ padding: 0, overflow: "visible" }}>
        <table style={{ width: "100%", fontSize: 13, borderCollapse: "collapse" }}>
          <thead>
            <tr style={{ background: C.bg, textAlign: "left", color: C.inkSoft }}>
              {["Producto", "Código", "Familia", `P. ${data.listaLabels?.minorista || "Minorista"}`, `P. ${data.listaLabels?.mayorista || "Mayorista"}`, data.listaLabels?.otro || "Otro precio", "Stock hoy", "Stock mín.", ""].map((h) => (
                <th key={h} style={{ padding: "10px 12px", fontWeight: 600 }}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {data.productos.map((p) => {
              const bajo = p.stockMinimo !== "" && p.stockMinimo != null && Number(p.stock) <= Number(p.stockMinimo);
              return (
                <React.Fragment key={p.id}>
                  <tr style={{ borderTop: `1px solid ${C.line}` }}>
                    <td style={{ padding: "8px 12px", fontWeight: 500 }}>{p.nombre}</td>
                    <td style={{ padding: "8px 12px" }}>
                      <TextInput
                        value={p.codigo || ""}
                        placeholder="—"
                        onChange={(e) => actualizarProducto(p.id, "codigo", e.target.value)}
                        style={{ width: 90, padding: "4px 8px" }}
                      />
                    </td>
                    <td style={{ padding: "8px 12px" }}>
                      <Select value={p.familia} onChange={(e) => actualizarProducto(p.id, "familia", e.target.value)} style={{ padding: "3px 6px", fontSize: 12.5 }}>
                        {data.familias.map((f) => <option key={f} value={f}>{f}</option>)}
                      </Select>
                    </td>
                    {["precioMinorista", "precioMayorista", "precioOtro"].map((campo) => (
                      <td key={campo} style={{ padding: "8px 12px" }}>
                        <TextInput
                          type="number"
                          value={p[campo]}
                          onChange={(e) => actualizarProducto(p.id, campo, Number(e.target.value))}
                          style={{ width: 85, padding: "4px 8px" }}
                        />
                      </td>
                    ))}
                    <td style={{ padding: "8px 12px", fontWeight: 600, color: bajo ? C.rust : C.ink }}>
                      {p.stock} {bajo && <AlertTriangle size={13} style={{ display: "inline", marginLeft: 4 }} />}
                    </td>
                    <td style={{ padding: "8px 12px" }}>
                      <TextInput
                        type="number"
                        value={p.stockMinimo}
                        placeholder="—"
                        onChange={(e) => actualizarProducto(p.id, "stockMinimo", e.target.value)}
                        style={{ width: 65, padding: "4px 8px" }}
                      />
                    </td>
                    <td style={{ padding: "8px 12px", whiteSpace: "nowrap" }}>
                      <Button variant="ghost" style={{ padding: "4px 8px", fontSize: 12 }} onClick={() => setCargaStockId(cargaStockId === p.id ? null : p.id)}>
                        <PackagePlus size={14} /> Stock
                      </Button>
                      <Trash2 size={15} style={{ cursor: "pointer", color: C.inkFaint, display: "inline", marginLeft: 10 }} onClick={() => eliminarProducto(p.id)} />
                    </td>
                  </tr>
                  {cargaStockId === p.id && (
                    <tr style={{ background: C.greenSoft }}>
                      <td colSpan={9} style={{ padding: "10px 12px" }}>
                        <div className="flex gap-3 items-end flex-wrap">
                          <Field label="Fecha">
                            <TextInput type="date" value={cargaForm.fecha} onChange={(e) => setCargaForm({ ...cargaForm, fecha: e.target.value })} />
                          </Field>
                          <Field label="Cantidad a sumar">
                            <TextInput type="number" value={cargaForm.cantidad} onChange={(e) => setCargaForm({ ...cargaForm, cantidad: e.target.value })} style={{ width: 100 }} />
                          </Field>
                          <Field label="Motivo">
                            <TextInput value={cargaForm.motivo} onChange={(e) => setCargaForm({ ...cargaForm, motivo: e.target.value })} style={{ width: 140 }} />
                          </Field>
                          <Button onClick={() => confirmarCarga(p)}><Check size={14} /> Confirmar</Button>
                          <Button variant="ghost" onClick={() => setCargaStockId(null)}>Cancelar</Button>
                        </div>
                      </td>
                    </tr>
                  )}
                </React.Fragment>
              );
            })}
            {data.productos.length === 0 && (
              <tr><td colSpan={9} style={{ padding: 24, textAlign: "center", color: C.inkFaint }}>Todavía no cargaste ningún producto.</td></tr>
            )}
          </tbody>
        </table>
      </Card>
    </div>
  );
}

/* ---------- Importar ---------- */
function findHeaderRow(sheet, mustContain) {
  const range = XLSX.utils.decode_range(sheet["!ref"]);
  for (let r = range.s.r; r <= Math.min(range.s.r + 6, range.e.r); r++) {
    const rowVals = [];
    for (let c = range.s.c; c <= range.e.c; c++) {
      const cell = sheet[XLSX.utils.encode_cell({ r, c })];
      rowVals.push(cell ? String(cell.v).trim().toLowerCase() : "");
    }
    if (mustContain.some((m) => rowVals.some((v) => v.includes(m)))) {
      return { rowIndex: r, headers: rowVals };
    }
  }
  return null;
}
function sheetRowsFromHeader(sheet, headerInfo) {
  const range = XLSX.utils.decode_range(sheet["!ref"]);
  const rows = [];
  for (let r = headerInfo.rowIndex + 1; r <= range.e.r; r++) {
    const obj = {};
    let hasData = false;
    for (let c = range.s.c; c <= range.e.c; c++) {
      const key = headerInfo.headers[c - range.s.c];
      if (!key) continue;
      const cell = sheet[XLSX.utils.encode_cell({ r, c })];
      if (cell && cell.v !== undefined && cell.v !== "") hasData = true;
      obj[key] = cell ? cell.v : "";
    }
    if (hasData) rows.push(obj);
  }
  return rows;
}

function pickByInclude(row, includes) {
  for (const k in row) {
    if (includes.some((inc) => k.includes(inc))) return row[k];
  }
  return undefined;
}
const FAMILIAS_EXCLUIDAS = ["aporte dueños", "aporte socios", "ingresos x préstamos", "ingresos por préstamos", "otros ingresos"];

function parseDatabaseSheet(sheet) {
  const range = XLSX.utils.decode_range(sheet["!ref"]);
  const familias = [], medios = [], puntos = [], rubros = [];
  const rubroTipo = {};
  const get = (colLetter, r1) => {
    const cell = sheet[colLetter + r1];
    return cell && cell.v !== undefined && cell.v !== "" ? String(cell.v).trim() : undefined;
  };
  for (let r = 4; r <= range.e.r + 1; r++) {
    const fam = get("A", r); if (fam) familias.push(fam);
    const med = get("C", r); if (med) medios.push(med);
    const pun = get("E", r); if (pun) puntos.push(pun);
    const rub = get("G", r);
    if (rub) {
      rubros.push(rub);
      const tip = get("H", r);
      if (tip) rubroTipo[rub] = tip.toLowerCase().startsWith("f") ? "fijo" : "variable";
    }
  }
  return { familias, medios, puntos, rubros, rubroTipo };
}

/* ---------- Importación genérica (ecommerce / WhatsApp) ---------- */
function leerPrimeraHoja(file, cb, onError) {
  const reader = new FileReader();
  reader.onload = (evt) => {
    try {
      const wb = XLSX.read(evt.target.result, { type: "array", cellDates: true });
      const sheet = wb.Sheets[wb.SheetNames[0]];
      const range = XLSX.utils.decode_range(sheet["!ref"]);
      const headers = [];
      for (let c = range.s.c; c <= range.e.c; c++) {
        const cell = sheet[XLSX.utils.encode_cell({ r: range.s.r, c })];
        headers.push(cell && cell.v !== undefined && cell.v !== "" ? String(cell.v).trim() : `Columna ${c + 1}`);
      }
      const rows = [];
      for (let r = range.s.r + 1; r <= range.e.r; r++) {
        const obj = {};
        let hasData = false;
        for (let c = range.s.c; c <= range.e.c; c++) {
          const key = headers[c - range.s.c];
          const cell = sheet[XLSX.utils.encode_cell({ r, c })];
          if (cell && cell.v !== undefined && cell.v !== "") hasData = true;
          obj[key] = cell ? cell.v : "";
        }
        if (hasData) rows.push(obj);
      }
      cb({ headers, rows });
    } catch (err) {
      onError();
    }
  };
  reader.readAsArrayBuffer(file);
}

function valorFecha(v) {
  return excelDateToStr(v);
}

function camposDestinoVentas() {
  return [
    { key: "idExterno", label: "N° de orden / ID (recomendado: evita duplicados)", requerido: false },
    { key: "fecha", label: "Fecha de la venta", requerido: true },
    { key: "producto", label: "Producto — nombre/descripción (opcional)", requerido: false },
    { key: "codigo", label: "Código de producto / SKU (opcional, si tus productos usan código)", requerido: false },
    { key: "cantidad", label: "Cantidad (opcional, 1 si no se indica)", requerido: false },
    { key: "precioUnitario", label: "Precio unitario del producto (si tu archivo lo trae por separado de la cantidad)", requerido: false },
    { key: "monto", label: "Monto de ESA línea/producto — no el total de todo el pedido (usar si no mapeaste Precio unitario)", requerido: false },
    { key: "medioPago", label: "Medio de pago (opcional; si no lo mapeás, se usa el que elijas abajo para todo el archivo)", requerido: false },
    { key: "descuento", label: "Descuento del pedido (opcional; si viene a nivel de todo el pedido, se reparte entre sus productos)", requerido: false },
    { key: "cliente", label: "Nombre del comprador (opcional)", requerido: false },
  ];
}
function camposDestinoCobros() {
  return [
    { key: "idExterno", label: "N° de orden / ID (debe coincidir con el usado al importar la venta)", requerido: true },
    { key: "fechaAcreditacion", label: "Fecha de acreditación", requerido: true },
    { key: "montoAcreditado", label: "Monto neto acreditado", requerido: true },
    { key: "comision", label: "Comisión descontada (opcional; si no está, se calcula sola)", requerido: false },
  ];
}

// Arma ventas nuevas a partir de un archivo mapeado, agrupando varios ítems bajo el mismo
// N° de orden (comparten ventaId), prorrateando el descuento del pedido entre sus líneas,
// y evitando reimportar órdenes que ya existían antes.
function construirVentasDesdeArchivo(archivo, mapeo, medioPagoFijo, puntoVentaFijo, familiaFija, data, mapeoMedios) {
  const existentesPrevio = new Set((data.ventas || []).map((v) => v.idExterno).filter(Boolean));
  const mediosDetectados = new Set();

  function configDeMedio(medio) {
    const esCtaCte = medio === MEDIO_CTA_CTE;
    const cfg = (data.medioConfig || {})[medio] || {};
    return {
      esCtaCte,
      diasAcreditacion: esCtaCte ? null : Number(cfg.diasAcreditacion) || 0,
      comisionPctEstimada: esCtaCte ? 0 : Number(cfg.comisionPct) || 0,
    };
  }

  // Paso 1: leer cada fila y agrupar por orden. Si no hay N° de orden mapeado (o viene vacío),
  // cada fila es su propia orden de un solo ítem.
  const ordenes = new Map();
  const duplicadas = [];
  const vistosDuplicados = new Set();
  let sinOrdenContador = 0;

  archivo.rows.forEach((row) => {
    const idExterno = mapeo.idExterno ? String(row[mapeo.idExterno] ?? "").trim() : "";
    const fecha = mapeo.fecha ? valorFecha(row[mapeo.fecha]) : "";
    const cantidad = mapeo.cantidad ? Number(row[mapeo.cantidad]) || 1 : 1;

    let precioUnitario = 0;
    let bruto = 0;
    if (mapeo.precioUnitario) {
      precioUnitario = Number(row[mapeo.precioUnitario]) || 0;
      bruto = precioUnitario * cantidad;
    } else if (mapeo.monto) {
      bruto = Number(row[mapeo.monto]) || 0;
      precioUnitario = cantidad ? bruto / cantidad : bruto;
    }
    if (!fecha || !bruto) return; // fila sin datos mínimos, se ignora

    if (idExterno && existentesPrevio.has(idExterno)) {
      if (!vistosDuplicados.has(idExterno)) { vistosDuplicados.add(idExterno); duplicadas.push(idExterno); }
      return;
    }

    const clave = idExterno || `__sin_orden_${sinOrdenContador++}`;
    if (!ordenes.has(clave)) {
      const descuentoOrden =
        mapeo.descuento && row[mapeo.descuento] !== undefined && row[mapeo.descuento] !== ""
          ? Number(row[mapeo.descuento]) || 0
          : 0;
      ordenes.set(clave, { idExterno, descuentoOrden, lineas: [] });
    }

    const codigoProducto = mapeo.codigo ? String(row[mapeo.codigo] ?? "").trim() : "";
    const productoNombre = mapeo.producto ? String(row[mapeo.producto] || "").trim() : "";
    const clienteNombre = mapeo.cliente ? String(row[mapeo.cliente] || "").trim() : "";
    const productoExistente = codigoProducto
      ? data.productos.find((p) => (p.codigo || "").trim().toLowerCase() === codigoProducto.toLowerCase())
      : productoNombre
      ? data.productos.find((p) => p.nombre.trim().toLowerCase() === productoNombre.toLowerCase())
      : null;

    let medioPago = medioPagoFijo;
    const medioDeFila = mapeo.medioPago ? String(row[mapeo.medioPago] || "").trim() : "";
    if (medioDeFila) {
      const destino = ((mapeoMedios || {})[medioDeFila] || medioDeFila).trim();
      const medioExistente = data.medios.find((m) => m.toLowerCase() === destino.toLowerCase());
      medioPago = medioExistente || destino;
      if (!medioExistente) mediosDetectados.add(destino);
    }

    ordenes.get(clave).lineas.push({
      fecha,
      cantidad,
      precioUnitario,
      bruto,
      productoId: productoExistente ? productoExistente.id : "",
      productoNombre: productoExistente ? productoExistente.nombre : (productoNombre || "Venta importada"),
      familia: productoExistente ? productoExistente.familia : (familiaFija || "General"),
      clienteNombre,
      medioPago,
    });
  });

  // Paso 2: por cada orden, repartir su descuento entre las líneas proporcionalmente al bruto de cada una.
  const nuevas = [];
  const mediosSinAcreditacion = new Set();
  ordenes.forEach((orden) => {
    const totalBrutoOrden = orden.lineas.reduce((a, l) => a + l.bruto, 0);
    const ventaId = uid();
    orden.lineas.forEach((l) => {
      const descuentoLinea = totalBrutoOrden ? (l.bruto / totalBrutoOrden) * orden.descuentoOrden : 0;
      const total = l.bruto - descuentoLinea;
      const { esCtaCte, diasAcreditacion, comisionPctEstimada } = configDeMedio(l.medioPago);
      if (!esCtaCte && !diasAcreditacion) mediosSinAcreditacion.add(l.medioPago);
      const fechaEstimadaAcreditacion = esCtaCte ? null : sumarDias(l.fecha, diasAcreditacion);
      const estadoCobro = esCtaCte ? undefined : diasAcreditacion > 0 ? "pendiente" : "acreditado";

      nuevas.push({
        id: uid(),
        ventaId,
        idExterno: orden.idExterno || undefined,
        fecha: l.fecha,
        productoId: l.productoId,
        productoNombre: l.productoNombre,
        familia: l.familia,
        cantidad: l.cantidad,
        puntoVenta: puntoVentaFijo || "Importado",
        lista: "importado",
        listaLabel: "Importado",
        precioUnitario: l.precioUnitario,
        totalBruto: l.bruto,
        descuentoPct: l.bruto ? (descuentoLinea / l.bruto) * 100 : 0,
        descuentoMonto: descuentoLinea,
        total,
        medioPago: l.medioPago,
        observaciones: l.clienteNombre ? `Importado — comprador: ${l.clienteNombre}` : "Importado",
        diasAcreditacion,
        comisionPctEstimada,
        fechaEstimadaAcreditacion,
        estadoCobro,
        confirmado: false,
      });
    });
  });

  return { nuevas, duplicadas, mediosNuevos: Array.from(mediosDetectados), mediosSinAcreditacion: Array.from(mediosSinAcreditacion) };
}

// Concilia ventas pendientes contra un reporte de pagos/acreditaciones, cruzando por idExterno
function construirConciliacionDesdeArchivo(archivo, mapeo, data) {
  const ventas = [...(data.ventas || [])];
  const gastosNuevos = [];
  const conciliadas = [];
  const sinMatch = [];

  archivo.rows.forEach((row) => {
    const idExterno = mapeo.idExterno ? String(row[mapeo.idExterno] ?? "").trim() : "";
    const fechaAcreditacion = mapeo.fechaAcreditacion ? valorFecha(row[mapeo.fechaAcreditacion]) : "";
    const montoAcreditado = mapeo.montoAcreditado ? Number(row[mapeo.montoAcreditado]) || 0 : 0;
    const comisionInformada =
      mapeo.comision && row[mapeo.comision] !== undefined && row[mapeo.comision] !== ""
        ? Number(row[mapeo.comision]) || 0
        : null;
    if (!idExterno || !fechaAcreditacion) return;

    const coincidencias = ventas
      .map((v, i) => ({ v, i }))
      .filter(({ v }) => v.idExterno === idExterno && v.estadoCobro === "pendiente" && !v.confirmado);

    if (coincidencias.length === 0) {
      sinMatch.push({ idExterno, montoAcreditado, fechaAcreditacion });
      return;
    }

    const sumaVenta = coincidencias.reduce((a, { v }) => a + v.total, 0);
    const comisionReal = comisionInformada != null ? comisionInformada : sumaVenta - montoAcreditado;
    const loteId = uid();

    coincidencias.forEach(({ v, i }) => {
      const comisionMonto = sumaVenta ? (v.total / sumaVenta) * comisionReal : 0;
      ventas[i] = {
        ...v,
        confirmado: true,
        estadoCobro: "acreditado",
        comisionMonto,
        comisionPct: v.total ? (comisionMonto / v.total) * 100 : 0,
        fechaAcreditacionReal: fechaAcreditacion,
        loteId,
      };
    });

    gastosNuevos.push({
      id: uid(),
      fecha: fechaAcreditacion,
      rubro: "Comisiones Corredores de Pago",
      detalle: `Comisión sobre orden ${idExterno} (importado, ${coincidencias.length} línea${coincidencias.length === 1 ? "" : "s"})`,
      monto: comisionReal,
      medioPago: coincidencias[0].v.medioPago,
      observaciones: "",
    });

    conciliadas.push({ idExterno, montoAcreditado, comisionReal, lineas: coincidencias.length });
  });

  return { ventas, gastosNuevos, conciliadas, sinMatch };
}

function ImportacionGenerica({ data, update }) {
  const [tipo, setTipo] = useState("ventas");
  const [archivo, setArchivo] = useState(null);
  const [perfilId, setPerfilId] = useState("");
  const [nombrePerfilNuevo, setNombrePerfilNuevo] = useState("");
  const [mapeoEdit, setMapeoEdit] = useState({});
  const [medioPagoFijo, setMedioPagoFijo] = useState(data.medios[0] || "");
  const [puntoVentaFijo, setPuntoVentaFijo] = useState(data.puntosVenta[0] || "");
  const [familiaFija, setFamiliaFija] = useState(data.familias[0] || "General");
  const [error, setError] = useState("");
  const [resultado, setResultado] = useState(null);
  const [justSaved, setJustSaved] = useState(false);
  const [editando, setEditando] = useState(false);
  const [confirmoRiesgo, setConfirmoRiesgo] = useState(false);
  const [mapeoMedios, setMapeoMedios] = useState({}); // valor tal cual viene en el archivo -> medio de pago del sistema
  const fileRef = useRef();

  const perfilesDelTipo = (data.perfilesImportacion || []).filter((p) => p.tipo === tipo);
  const campos = tipo === "ventas" ? camposDestinoVentas() : camposDestinoCobros();
  const perfilActivo = perfilId && perfilId !== "__nuevo__" ? perfilesDelTipo.find((p) => p.id === perfilId) : null;

  function cambiarTipo(t) {
    setTipo(t);
    setArchivo(null);
    setPerfilId("");
    setMapeoEdit({});
    setMapeoMedios({});
    setResultado(null);
    setError("");
    setEditando(false);
  }

  function entrarModoEdicion() {
    if (!perfilActivo) return;
    setMapeoEdit({ ...perfilActivo.mapeo });
    setMapeoMedios({ ...(perfilActivo.mapeoMedios || {}) });
    setMedioPagoFijo(perfilActivo.medioPagoFijo || data.medios[0] || "");
    setPuntoVentaFijo(perfilActivo.puntoVentaFijo || data.puntosVenta[0] || "");
    setFamiliaFija(perfilActivo.familiaFija || data.familias[0] || "General");
    setNombrePerfilNuevo(perfilActivo.nombre);
    setEditando(true);
    setResultado(null);
    setError("");
  }

  function handleFile(e) {
    const file = e.target.files[0];
    if (!file) return;
    setError("");
    setResultado(null);
    leerPrimeraHoja(
      file,
      (leido) => {
        if (leido.rows.length === 0) { setError("El archivo no tiene filas de datos debajo del encabezado."); return; }
        setArchivo(leido);
      },
      () => setError("No pude leer el archivo. Verificá que sea un .xlsx, .xls o .csv válido.")
    );
  }

  function procesarConMapeo(mapeo, medioFijo, ptoFijo, famFija, dicMedios) {
    setError("");
    setConfirmoRiesgo(false);
    try {
      if (tipo === "ventas") {
        if (!mapeo.fecha || (!mapeo.monto && !mapeo.precioUnitario)) {
          setError("Mapeá al menos Fecha, y Precio unitario o Monto de la línea.");
          return;
        }
        if (mapeo.medioPago) {
          const valores = Array.from(new Set(archivo.rows.map((r) => String(r[mapeo.medioPago] || "").trim()).filter(Boolean)));
          const faltan = valores.filter((v) => !(dicMedios || {})[v]);
          if (faltan.length > 0) {
            setError(`Falta traducir estos valores de la columna de medio de pago a uno de tus medios: ${faltan.join(", ")}.`);
            return;
          }
        }
        const { nuevas, duplicadas, mediosNuevos, mediosSinAcreditacion } = construirVentasDesdeArchivo(archivo, mapeo, medioFijo, ptoFijo, famFija, data, dicMedios || {});
        setResultado({ modo: "ventas", nuevas, duplicadas, mediosNuevos, mediosSinAcreditacion, mapeo, medioFijo, ptoFijo, famFija, dicMedios: dicMedios || {} });
      } else {
        if (!mapeo.idExterno || !mapeo.fechaAcreditacion || !mapeo.montoAcreditado) {
          setError("Mapeá N° de orden, Fecha de acreditación y Monto acreditado antes de continuar.");
          return;
        }
        const { ventas, gastosNuevos, conciliadas, sinMatch } = construirConciliacionDesdeArchivo(archivo, mapeo, data);
        setResultado({ modo: "cobros", ventas, gastosNuevos, conciliadas, sinMatch, mapeo });
      }
    } catch (err) {
      setError("No pude procesar el archivo con este mapeo. Revisá que la columna de fecha tenga fechas válidas y la de monto tenga números. Detalle: " + (err && err.message ? err.message : String(err)));
    }
  }

  function aplicarPerfilGuardado() {
    if (!archivo || !perfilActivo) return;
    const faltantesCols = Object.entries(perfilActivo.mapeo)
      .filter(([, columna]) => columna && !archivo.headers.includes(columna))
      .map(([campo]) => campo);
    if (faltantesCols.length > 0) {
      setError(`Este archivo no tiene las columnas que el perfil "${perfilActivo.nombre}" espera (${faltantesCols.join(", ")}). Elegí "Editar este mapeo" para volver a mapear.`);
      return;
    }

    const dicMedios = perfilActivo.mapeoMedios || {};
    if (tipo === "ventas" && perfilActivo.mapeo.medioPago) {
      const valores = Array.from(new Set(archivo.rows.map((r) => String(r[perfilActivo.mapeo.medioPago] || "").trim()).filter(Boolean)));
      const faltan = valores.filter((v) => !dicMedios[v]);
      if (faltan.length > 0) {
        entrarModoEdicion();
        setMapeoMedios({ ...dicMedios });
        setError(`Este archivo trae valores de medio de pago que el perfil todavía no tiene traducidos: ${faltan.join(", ")}. Completalos abajo (quedaron resaltados) y guardá los cambios.`);
        return;
      }
    }
    procesarConMapeo(perfilActivo.mapeo, perfilActivo.medioPagoFijo, perfilActivo.puntoVentaFijo, perfilActivo.familiaFija, dicMedios);
  }

  function confirmarNuevoMapeo() {
    if (!nombrePerfilNuevo.trim()) { setError('Poné un nombre para este perfil (ej. "Tiendanube - Ventas").'); return; }
    procesarConMapeo(mapeoEdit, medioPagoFijo, puntoVentaFijo, familiaFija, mapeoMedios);
  }

  function confirmarImportacion() {
    if (!resultado) return;
    let perfiles = data.perfilesImportacion || [];
    if (perfilId === "__nuevo__") {
      perfiles = [
        ...perfiles,
        {
          id: uid(),
          nombre: nombrePerfilNuevo.trim(),
          tipo,
          mapeo: resultado.mapeo,
          medioPagoFijo: resultado.medioFijo,
          puntoVentaFijo: resultado.ptoFijo,
          familiaFija: resultado.famFija,
          mapeoMedios: resultado.dicMedios || {},
        },
      ];
    } else if (editando && perfilActivo) {
      perfiles = perfiles.map((p) =>
        p.id === perfilActivo.id
          ? {
              ...p,
              nombre: nombrePerfilNuevo.trim() || p.nombre,
              mapeo: resultado.mapeo,
              medioPagoFijo: resultado.medioFijo,
              puntoVentaFijo: resultado.ptoFijo,
              familiaFija: resultado.famFija,
              mapeoMedios: resultado.dicMedios || {},
            }
          : p
      );
    }

    if (resultado.modo === "ventas") {
      const puntosSet = new Set(data.puntosVenta);
      if (resultado.ptoFijo) puntosSet.add(resultado.ptoFijo);
      const familiasSet = new Set(data.familias);
      if (resultado.famFija) familiasSet.add(resultado.famFija);
      const mediosSet = new Set(data.medios);
      (resultado.mediosNuevos || []).forEach((m) => mediosSet.add(m));
      update({
        ...data,
        ventas: [...resultado.nuevas, ...data.ventas],
        puntosVenta: Array.from(puntosSet),
        familias: Array.from(familiasSet),
        medios: Array.from(mediosSet),
        perfilesImportacion: perfiles,
      });
    } else {
      update({
        ...data,
        ventas: resultado.ventas,
        gastos: [...resultado.gastosNuevos, ...data.gastos],
        perfilesImportacion: perfiles,
      });
    }
    setResultado(null);
    setArchivo(null);
    setMapeoEdit({});
    setMapeoMedios({});
    setPerfilId("");
    setEditando(false);
    setConfirmoRiesgo(false);
    if (fileRef.current) fileRef.current.value = "";
    setJustSaved(true);
    setTimeout(() => setJustSaved(false), 3000);
  }

  return (
    <div className="flex flex-col gap-4">
      <div className="flex gap-2">
        <Button variant={tipo === "ventas" ? "primary" : "ghost"} onClick={() => cambiarTipo("ventas")}>Ventas</Button>
        <Button variant={tipo === "cobros" ? "primary" : "ghost"} onClick={() => cambiarTipo("cobros")}>Cobros / Acreditaciones</Button>
      </div>

      <div style={{ fontSize: 12.5, color: C.inkSoft }}>
        {tipo === "ventas"
          ? "Para cargar ventas exportadas de una plataforma de ecommerce o un formulario de WhatsApp."
          : 'Para cargar el reporte de pagos/acreditaciones (ej. "Pagos Nube" de Tiendanube) y conciliarlo automáticamente con las ventas ya importadas, cruzando por N° de orden.'}
      </div>

      <Card style={{ padding: 18 }}>
        <div className="flex flex-wrap gap-3 items-end" style={{ marginBottom: 12 }}>
          <Field label="Perfil de mapeo">
            <select
              style={inputStyle}
              value={perfilId}
              onChange={(e) => { setPerfilId(e.target.value); setResultado(null); setError(""); setMapeoEdit({}); setMapeoMedios({}); setEditando(false); }}
            >
              <option value="">Elegir...</option>
              {perfilesDelTipo.map((p) => (
                <option key={p.id} value={p.id}>{p.nombre}</option>
              ))}
              <option value="__nuevo__">+ Crear nuevo mapeo</option>
            </select>
          </Field>
          <Field label="Archivo (.xlsx, .xls o .csv)">
            <input ref={fileRef} type="file" accept=".xlsx,.xls,.csv" onChange={handleFile} style={{ fontSize: 13 }} />
          </Field>
        </div>

        {error && <div style={{ color: C.rust, fontSize: 13, marginBottom: 10 }}>{error}</div>}
        {justSaved && <div style={{ color: C.green, fontSize: 13, marginBottom: 10 }}>✓ Importación aplicada</div>}

        {archivo && (perfilId === "__nuevo__" || editando) && (
          <div className="flex flex-col gap-3" style={{ marginTop: 6 }}>
            <Field label="Nombre de este perfil (para reutilizarlo la próxima vez)">
              <TextInput value={nombrePerfilNuevo} onChange={(e) => setNombrePerfilNuevo(e.target.value)} placeholder='Ej. "Tiendanube - Ventas"' style={{ width: 280 }} />
            </Field>

            <div style={{ fontSize: 12.5, color: C.inkSoft }}>Detectamos estas columnas en tu archivo — decinos qué es cada una:</div>
            <div className="flex flex-wrap gap-3">
              {campos.map((c) => (
                <Field key={c.key} label={c.label + (c.requerido ? " *" : "")}>
                  <select
                    style={{ ...inputStyle, width: 220 }}
                    value={mapeoEdit[c.key] || ""}
                    onChange={(e) => setMapeoEdit({ ...mapeoEdit, [c.key]: e.target.value })}
                  >
                    <option value="">No corresponde / no está</option>
                    {archivo.headers.map((h) => (
                      <option key={h} value={h}>{h}</option>
                    ))}
                  </select>
                </Field>
              ))}
            </div>

            {tipo === "ventas" && mapeoEdit.medioPago && (
              (() => {
                const valoresDetectados = Array.from(
                  new Set(archivo.rows.map((r) => String(r[mapeoEdit.medioPago] || "").trim()).filter(Boolean))
                );
                if (valoresDetectados.length === 0) return null;
                return (
                  <div className="flex flex-col gap-2">
                    <div style={{ fontSize: 12.5, color: C.inkSoft }}>
                      Encontramos estos valores en la columna de medio de pago del archivo — decinos a cuál de tus medios corresponde cada uno (se traduce una sola vez, después queda guardado en este perfil):
                    </div>
                    <div className="flex flex-wrap gap-3">
                      {valoresDetectados.map((val) => (
                        <Field key={val} label={val}>
                          <select
                            style={{ ...inputStyle, width: 210, border: mapeoMedios[val] ? undefined : `1px solid ${C.rust}` }}
                            value={mapeoMedios[val] || ""}
                            onChange={(e) => setMapeoMedios({ ...mapeoMedios, [val]: e.target.value })}
                          >
                            <option value="">Elegir medio...</option>
                            {data.medios.map((m) => <option key={m} value={m}>{m}</option>)}
                            <option value={val}>+ Crear medio nuevo: "{val}"</option>
                          </select>
                        </Field>
                      ))}
                    </div>
                  </div>
                );
              })()
            )}

            {tipo === "ventas" && (
              <div className="flex flex-wrap gap-3">
                <Field label="Medio de pago por defecto (se usa si no mapeás la columna de medio, o si una fila viene vacía)">
                  <select style={{ ...inputStyle, width: 240 }} value={medioPagoFijo} onChange={(e) => setMedioPagoFijo(e.target.value)}>
                    {data.medios.map((m) => <option key={m} value={m}>{m}</option>)}
                  </select>
                </Field>
                <Field label="Punto de venta">
                  <TextInput value={puntoVentaFijo} onChange={(e) => setPuntoVentaFijo(e.target.value)} style={{ width: 160 }} placeholder="Ej. Tienda Online" />
                </Field>
                <Field label="Familia">
                  <TextInput value={familiaFija} onChange={(e) => setFamiliaFija(e.target.value)} style={{ width: 160 }} placeholder="Ej. Importado" />
                </Field>
              </div>
            )}

            <div className="flex gap-2">
              <Button onClick={confirmarNuevoMapeo}>{editando ? "Guardar cambios y ver qué se va a importar" : "Ver qué se va a importar"}</Button>
              {editando && <Button variant="ghost" onClick={() => setEditando(false)}>Cancelar edición</Button>}
            </div>
          </div>
        )}

        {archivo && perfilActivo && !editando && (
          <div className="flex gap-2" style={{ marginTop: 6 }}>
            <Button onClick={aplicarPerfilGuardado}>Aplicar perfil "{perfilActivo.nombre}" y ver qué se va a importar</Button>
            <Button variant="ghost" onClick={entrarModoEdicion}>Editar este mapeo</Button>
          </div>
        )}
      </Card>

      {resultado && resultado.modo === "ventas" && (
        <Card style={{ padding: 18 }}>
          <div style={{ fontWeight: 600, marginBottom: 8 }}>Se van a importar {resultado.nuevas.length} ventas nuevas</div>
          {resultado.duplicadas.length > 0 && (
            <div style={{ fontSize: 12.5, color: C.inkSoft, marginBottom: 10 }}>
              Se omitieron {resultado.duplicadas.length} orden{resultado.duplicadas.length === 1 ? "" : "es"} porque ya existían en el sistema (evita duplicar): {resultado.duplicadas.join(", ")}
            </div>
          )}
          {resultado.mediosNuevos && resultado.mediosNuevos.length > 0 && (
            <div style={{ fontSize: 12.5, color: C.inkSoft, marginBottom: 10 }}>
              El archivo trae medios de pago que no tenías cargados — se van a agregar a Configuración: {resultado.mediosNuevos.join(", ")}.
              Después podés configurarles días de acreditación y comisión si corresponde.
            </div>
          )}
          {resultado.mediosSinAcreditacion && resultado.mediosSinAcreditacion.length > 0 && (
            <div style={{ background: C.rustSoft || "#fdeee9", border: `1px solid ${C.rust}`, borderRadius: 6, padding: 12, marginBottom: 10 }}>
              <div style={{ fontSize: 13, color: C.rust, fontWeight: 600, marginBottom: 4 }}>
                Atención: estos medios no tienen días de acreditación configurados
              </div>
              <div style={{ fontSize: 12.5, color: C.ink, marginBottom: 8 }}>
                {resultado.mediosSinAcreditacion.join(", ")} — sin esa configuración, las ventas con ese medio se van a marcar como <b>ya cobradas al instante</b>, y no van a aparecer en Cobros Pendientes para conciliar contra el reporte real de pagos/liquidaciones. Si corresponden a un canal con liquidación diferida (por ejemplo, tarjetas de una tienda online), te conviene cancelar, ir a Configuración a cargarles días de acreditación, y volver a importar.
              </div>
              <label style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 12.5, color: C.ink }}>
                <input type="checkbox" checked={confirmoRiesgo} onChange={(e) => setConfirmoRiesgo(e.target.checked)} />
                Entiendo el riesgo, quiero continuar igual dándolas por cobradas al instante.
              </label>
            </div>
          )}
          {resultado.nuevas.length > 0 && (
            <div style={{ maxHeight: 220, overflowY: "auto", marginBottom: 12 }}>
              <table style={{ width: "100%", fontSize: 12.5, borderCollapse: "collapse" }}>
                <thead>
                  <tr style={{ textAlign: "left", color: C.inkSoft }}>
                    <th style={{ padding: "4px 8px" }}>Fecha</th>
                    <th style={{ padding: "4px 8px" }}>Orden</th>
                    <th style={{ padding: "4px 8px" }}>Producto</th>
                    <th style={{ padding: "4px 8px" }}>Cant.</th>
                    <th style={{ padding: "4px 8px" }}>P. unitario</th>
                    <th style={{ padding: "4px 8px" }}>Desc.</th>
                    <th style={{ padding: "4px 8px" }}>Monto</th>
                    <th style={{ padding: "4px 8px" }}>Medio</th>
                    <th style={{ padding: "4px 8px" }}>Estado de cobro</th>
                  </tr>
                </thead>
                <tbody>
                  {resultado.nuevas.slice(0, 30).map((v) => (
                    <tr key={v.id} style={{ borderTop: `1px solid ${C.line}` }}>
                      <td style={{ padding: "4px 8px" }}>{v.fecha}</td>
                      <td style={{ padding: "4px 8px" }}>{v.idExterno || "—"}</td>
                      <td style={{ padding: "4px 8px" }}>{v.productoNombre}</td>
                      <td style={{ padding: "4px 8px" }}>{v.cantidad}</td>
                      <td style={{ padding: "4px 8px" }}>{money(v.precioUnitario)}</td>
                      <td style={{ padding: "4px 8px" }}>{v.descuentoMonto ? money(v.descuentoMonto) : "—"}</td>
                      <td style={{ padding: "4px 8px" }}>{money(v.total)}</td>
                      <td style={{ padding: "4px 8px" }}>{v.medioPago}</td>
                      <td style={{ padding: "4px 8px" }}>{v.estadoCobro || "acreditado"}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
              {resultado.nuevas.length > 30 && (
                <div style={{ fontSize: 12, color: C.inkFaint, marginTop: 4 }}>...y {resultado.nuevas.length - 30} más.</div>
              )}
            </div>
          )}
          <div className="flex gap-2">
            <Button
              onClick={confirmarImportacion}
              disabled={
                resultado.nuevas.length === 0 ||
                (resultado.mediosSinAcreditacion && resultado.mediosSinAcreditacion.length > 0 && !confirmoRiesgo)
              }
            >
              <Check size={15} /> Confirmar importación
            </Button>
            <Button variant="ghost" onClick={() => setResultado(null)}>Cancelar</Button>
          </div>
        </Card>
      )}

      {resultado && resultado.modo === "cobros" && (
        <Card style={{ padding: 18 }}>
          <div style={{ fontWeight: 600, marginBottom: 8 }}>Se van a conciliar {resultado.conciliadas.length} órdenes</div>
          {resultado.sinMatch.length > 0 && (
            <div style={{ fontSize: 12.5, color: C.rust, marginBottom: 10 }}>
              {resultado.sinMatch.length} fila{resultado.sinMatch.length === 1 ? "" : "s"} no encontraron ninguna venta pendiente con ese N° de orden
              (quizás todavía no importaste esa venta, o ya estaba conciliada). Podés revisarlas a mano en "Cobros pendientes".
            </div>
          )}
          {resultado.conciliadas.length > 0 && (
            <div style={{ maxHeight: 220, overflowY: "auto", marginBottom: 12 }}>
              <table style={{ width: "100%", fontSize: 12.5, borderCollapse: "collapse" }}>
                <thead>
                  <tr style={{ textAlign: "left", color: C.inkSoft }}>
                    <th style={{ padding: "4px 8px" }}>Orden</th>
                    <th style={{ padding: "4px 8px" }}>Líneas</th>
                    <th style={{ padding: "4px 8px" }}>Acreditado</th>
                    <th style={{ padding: "4px 8px" }}>Comisión calculada</th>
                  </tr>
                </thead>
                <tbody>
                  {resultado.conciliadas.map((c, i) => (
                    <tr key={i} style={{ borderTop: `1px solid ${C.line}` }}>
                      <td style={{ padding: "4px 8px" }}>{c.idExterno}</td>
                      <td style={{ padding: "4px 8px" }}>{c.lineas}</td>
                      <td style={{ padding: "4px 8px" }}>{money(c.montoAcreditado)}</td>
                      <td style={{ padding: "4px 8px" }}>{money(c.comisionReal)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
          {resultado.sinMatch.length > 0 && (
            <div style={{ fontSize: 12, color: C.inkFaint, marginBottom: 12 }}>
              Sin coincidencia: {resultado.sinMatch.map((s) => s.idExterno).join(", ")}
            </div>
          )}
          <div className="flex gap-2">
            <Button onClick={confirmarImportacion} disabled={resultado.conciliadas.length === 0}><Check size={15} /> Confirmar conciliación</Button>
            <Button variant="ghost" onClick={() => setResultado(null)}>Cancelar</Button>
          </div>
        </Card>
      )}
    </div>
  );
}

function ImportarView({ data, update }) {
  const [modo, setModo] = useState("clasico");
  const [preview, setPreview] = useState(null);
  const [error, setError] = useState("");
  const fileRef = useRef();

  function handleFile(e) {
    const file = e.target.files[0];
    if (!file) return;
    setError("");
    const reader = new FileReader();
    reader.onload = (evt) => {
      try {
        const wb = XLSX.read(evt.target.result, { type: "array", cellDates: true });
        const sheetNames = wb.SheetNames;
        const stockSheetName = sheetNames.find((n) => /stock/i.test(n));
        const ingresosSheetName = sheetNames.find((n) => /ingres/i.test(n));
        const egresosSheetName = sheetNames.find((n) => /egres/i.test(n));
        const databaseSheetName = sheetNames.find((n) => /database/i.test(n));

        const productosNuevos = [];
        const ventasNuevas = [];
        const gastosNuevos = [];
        let baseDatos = null;

        if (stockSheetName) {
          const sheet = wb.Sheets[stockSheetName];
          const header = findHeaderRow(sheet, ["descripci"]);
          if (header) {
            const rows = sheetRowsFromHeader(sheet, header);
            rows.forEach((row) => {
              const nombre = row["descripción"] || row["descripcion"];
              if (!nombre) return;
              const familia = row["familia"] ? String(row["familia"]).trim() : "General";
              if (FAMILIAS_EXCLUIDAS.includes(familia.toLowerCase())) return;

              const pMinorista = pickByInclude(row, ["minorista"]);
              const pMayorista = pickByInclude(row, ["mayorista"]);
              const pOtro = pickByInclude(row, ["otro precio", "precio otro"]);
              const huboListas = pMinorista !== undefined || pMayorista !== undefined || pOtro !== undefined;
              const precioUnico = Number(row["precio de venta"]) || 0;
              const stock = Number(pickByInclude(row, ["stock hoy", "stock inicial"])) || 0;

              productosNuevos.push({
                id: uid(),
                nombre: String(nombre).trim(),
                familia,
                precioMinorista: huboListas ? Number(pMinorista) || 0 : precioUnico,
                precioMayorista: huboListas ? Number(pMayorista) || 0 : precioUnico,
                precioOtro: huboListas ? Number(pOtro) || 0 : precioUnico,
                stock,
                stockMinimo: "",
              });
            });
          }
        }
        if (ingresosSheetName) {
          const sheet = wb.Sheets[ingresosSheetName];
          const header = findHeaderRow(sheet, ["fecha"]);
          if (header) {
            const rows = sheetRowsFromHeader(sheet, header);
            rows.forEach((row) => {
              const nombre = row["detalle"];
              if (!nombre || !row["fecha"]) return;
              ventasNuevas.push({
                id: uid(),
                fecha: excelDateToStr(row["fecha"]),
                productoNombre: String(nombre).trim(),
                familia: row["familia"] ? String(row["familia"]).trim() : "General",
                cantidad: Number(row["unidades"]) || 0,
                puntoVenta: row["punto de venta"] ? String(row["punto de venta"]).trim() : "Importado",
                lista: "importado",
                listaLabel: "Importado",
                precioUnitario: Number(row["monto producto"]) || 0,
                total: Number(row["total linea"]) || (Number(row["monto producto"]) || 0) * (Number(row["unidades"]) || 0),
                medioPago: row["medio de pago"] ? String(row["medio de pago"]).trim() : "",
              });
            });
          }
        }
        if (egresosSheetName) {
          const sheet = wb.Sheets[egresosSheetName];
          const header = findHeaderRow(sheet, ["fecha"]);
          if (header) {
            const rows = sheetRowsFromHeader(sheet, header);
            rows.forEach((row) => {
              if (!row["fecha"] || !row["monto"]) return;
              gastosNuevos.push({
                id: uid(),
                fecha: excelDateToStr(row["fecha"]),
                rubro: row["rubro"] ? String(row["rubro"]).trim() : "Otros",
                detalle: row["detalle egreso"] ? String(row["detalle egreso"]).trim() : "",
                monto: Number(row["monto"]) || 0,
                medioPago: row["medio de pago"] ? String(row["medio de pago"]).trim() : "",
              });
            });
          }
        }
        if (databaseSheetName) {
          baseDatos = parseDatabaseSheet(wb.Sheets[databaseSheetName]);
        }

        if (!productosNuevos.length && !ventasNuevas.length && !gastosNuevos.length && !baseDatos) {
          setError("No encontré datos reconocibles. Revisá que el archivo tenga las solapas Stock y Ps, INGRESOS, EGRESOS y/o DATABASE con los mismos encabezados de siempre.");
          setPreview(null);
          return;
        }
        setPreview({ productosNuevos, ventasNuevas, gastosNuevos, baseDatos });
      } catch (err) {
        setError("No pude leer el archivo. Verificá que sea un .xlsx válido.");
        setPreview(null);
      }
    };
    reader.readAsArrayBuffer(file);
  }

  function confirmar() {
    if (!preview) return;
    // merge productos by nombre (case-insensitive) instead de duplicar
    const productos = [...data.productos];
    const familiasSet = new Set(data.familias);
    preview.productosNuevos.forEach((np) => {
      familiasSet.add(np.familia);
      const idx = productos.findIndex((p) => p.nombre.toLowerCase() === np.nombre.toLowerCase());
      if (idx >= 0) productos[idx] = { ...productos[idx], ...np, id: productos[idx].id };
      else productos.push(np);
    });
    const puntosSet = new Set(data.puntosVenta);
    const rubrosSet = new Set(data.rubros);
    const mediosSet = new Set(data.medios);
    let rubroTipo = { ...(data.rubroTipo || {}) };
    const ventas = [...data.ventas];
    preview.ventasNuevas.forEach((nv) => {
      const prod = productos.find((p) => p.nombre.toLowerCase() === nv.productoNombre.toLowerCase());
      if (prod) puntosSet.add(nv.puntoVenta);
      if (nv.medioPago) mediosSet.add(nv.medioPago);
      ventas.push({ ...nv, productoId: prod ? prod.id : "" });
    });
    const gastos = [...data.gastos];
    preview.gastosNuevos.forEach((ng) => {
      rubrosSet.add(ng.rubro);
      if (ng.medioPago) mediosSet.add(ng.medioPago);
      gastos.push(ng);
    });
    if (preview.baseDatos) {
      preview.baseDatos.familias.forEach((f) => familiasSet.add(f));
      preview.baseDatos.medios.forEach((m) => mediosSet.add(m));
      preview.baseDatos.puntos.forEach((p) => puntosSet.add(p));
      preview.baseDatos.rubros.forEach((r) => rubrosSet.add(r));
      rubroTipo = { ...rubroTipo, ...preview.baseDatos.rubroTipo };
    }

    update({
      ...data,
      productos,
      ventas,
      gastos,
      rubroTipo,
      familias: Array.from(familiasSet),
      puntosVenta: Array.from(puntosSet),
      rubros: Array.from(rubrosSet),
      medios: Array.from(mediosSet),
    });
    setPreview(null);
    if (fileRef.current) fileRef.current.value = "";
  }

  return (
    <div className="flex flex-col gap-5">
      <div>
        <h1 style={{ fontSize: 21, fontWeight: 700, color: C.ink, margin: 0 }}>Importar</h1>
        <p style={{ fontSize: 13, color: C.inkSoft, margin: "2px 0 0", maxWidth: 620 }}>
          Elegí qué querés importar.
        </p>
      </div>

      <div className="flex gap-2">
        <Button variant={modo === "clasico" ? "primary" : "ghost"} onClick={() => setModo("clasico")}>Excel clásico</Button>
        <Button variant={modo === "generico" ? "primary" : "ghost"} onClick={() => setModo("generico")}>Ecommerce / WhatsApp</Button>
      </div>

      {modo === "clasico" && (
        <>
          <p style={{ fontSize: 13, color: C.inkSoft, margin: 0, maxWidth: 560 }}>
            Subí un Excel con el mismo formato de siempre (solapas "Stock y Ps", "INGRESOS" y "EGRESOS") y se carga todo de una vez.
            Ideal para migrar el historial de un cliente al sistema.
          </p>

          <Card style={{ padding: 24, textAlign: "center" }}>
            <Upload size={28} style={{ color: C.green, margin: "0 auto 10px" }} />
            <input ref={fileRef} type="file" accept=".xlsx,.xls" onChange={handleFile} style={{ fontSize: 13 }} />
            {error && <div style={{ color: C.rust, fontSize: 13, marginTop: 10 }}>{error}</div>}
          </Card>

          {preview && (
            <Card style={{ padding: 18 }}>
              <div style={{ fontWeight: 600, marginBottom: 10 }}>Se encontró:</div>
              <ul style={{ fontSize: 14, color: C.ink, lineHeight: 1.9, paddingLeft: 18 }}>
                <li>{preview.productosNuevos.length} productos (precios por lista y stock)</li>
                <li>{preview.ventasNuevas.length} ventas históricas</li>
                <li>{preview.gastosNuevos.length} gastos históricos</li>
                {preview.baseDatos && (
                  <li>
                    Configuración desde DATABASE: {preview.baseDatos.familias.length} familias, {preview.baseDatos.medios.length} medios de pago,{" "}
                    {preview.baseDatos.puntos.length} puntos de venta, {preview.baseDatos.rubros.length} rubros
                  </li>
                )}
              </ul>
              <div style={{ fontSize: 12.5, color: C.inkSoft, marginBottom: 14 }}>
                Si el Stock tenía columnas separadas por lista (Minorista/Mayorista/Otro), se toman tal cual; si no, se usa el precio único para las 3. Los productos que ya existan con el mismo nombre se actualizan, no se duplican.
              </div>
              <div className="flex gap-2">
                <Button onClick={confirmar}><Check size={15} /> Confirmar importación</Button>
                <Button variant="ghost" onClick={() => setPreview(null)}>Cancelar</Button>
              </div>
            </Card>
          )}
        </>
      )}

      {modo === "generico" && <ImportacionGenerica data={data} update={update} />}
    </div>
  );
}

/* ---------- Movimientos de Caja ---------- */
function MovimientosView({ data, update }) {
  const [kind, setKind] = useState("motivo");
  const [verHistorico, setVerHistorico] = useState(false);
  const [localError, setLocalError] = useState("");
  const [justSaved, setJustSaved] = useState(false);
  const mediosCaja = data.medios.filter((m) => m !== MEDIO_CTA_CTE);
  const [form, setForm] = useState({
    fecha: todayStr(),
    motivoId: (MOTIVOS_MOVIMIENTO[0] || {}).id || "",
    monto: "",
    medioPago: mediosCaja[0] || "",
    medioOrigen: mediosCaja[0] || "",
    medioDestino: mediosCaja[1] || mediosCaja[0] || "",
    observaciones: "",
    clienteId: "",
  });

  const motivo = MOTIVOS_MOVIMIENTO.find((m) => m.id === form.motivoId) || MOTIVOS_MOVIMIENTO[0];

  function submit() {
    setLocalError("");
    try {
      const monto = Number(form.monto) || 0;
      if (!monto) { setLocalError("Falta indicar un monto mayor a cero."); return; }
      if (motivo?.requiereCliente && !form.clienteId) { setLocalError("Este motivo requiere elegir un cliente."); return; }
      let nuevo;
      if (kind === "transferencia") {
        if (!form.medioOrigen || !form.medioDestino) { setLocalError("Elegí un medio de origen y uno de destino."); return; }
        if (form.medioOrigen === form.medioDestino) { setLocalError("El medio de origen y destino no pueden ser el mismo."); return; }
        nuevo = {
          id: uid(),
          fecha: form.fecha,
          kind: "transferencia",
          medioOrigen: form.medioOrigen,
          medioDestino: form.medioDestino,
          monto,
          observaciones: form.observaciones,
        };
      } else {
        if (!motivo) { setLocalError("No hay motivos configurados."); return; }
        const cliente = motivo.requiereCliente ? (data.clientes || []).find((c) => c.id === form.clienteId) : null;
        nuevo = {
          id: uid(),
          fecha: form.fecha,
          kind: "motivo",
          motivoId: motivo.id,
          motivoLabel: motivo.label,
          tipo: motivo.tipo,
          flujo: motivo.flujo,
          monto,
          medioPago: form.medioPago,
          observaciones: form.observaciones,
          clienteId: cliente ? cliente.id : undefined,
          clienteNombre: cliente ? cliente.nombre : undefined,
        };
      }
      update({ ...data, movimientos: [nuevo, ...(data.movimientos || [])] });
      setForm({
        fecha: todayStr(),
        motivoId: (MOTIVOS_MOVIMIENTO[0] || {}).id || "",
        monto: "",
        medioPago: mediosCaja[0] || "",
        medioOrigen: mediosCaja[0] || "",
        medioDestino: mediosCaja[1] || mediosCaja[0] || "",
        observaciones: "",
        clienteId: "",
      });
      setJustSaved(true);
      setTimeout(() => setJustSaved(false), 2500);
    } catch (err) {
      setLocalError("Error: " + (err?.message || String(err)));
    }
  }
  function eliminar(id) {
    update({ ...data, movimientos: (data.movimientos || []).filter((m) => m.id !== id) });
  }

  return (
    <div className="flex flex-col gap-5">
      <div>
        <h1 style={{ fontSize: 21, fontWeight: 700, color: C.ink, margin: 0 }}>Movimientos de Caja</h1>
        <p style={{ fontSize: 13, color: C.inkSoft, margin: "2px 0 0", maxWidth: 560 }}>
          Todo lo que no es venta ni gasto operativo: aportes, préstamos, ajustes y traspasos entre medios de pago.
          Afecta tu Arqueo de Caja, pero no tus estadísticas de ventas ni el resultado operativo.
        </p>
      </div>

      <Card style={{ padding: 18 }}>
        <div className="flex gap-2" style={{ marginBottom: 14 }}>
          <Button variant={kind === "motivo" ? "primary" : "ghost"} type="button" onClick={() => setKind("motivo")}>Movimiento</Button>
          <Button variant={kind === "transferencia" ? "primary" : "ghost"} type="button" onClick={() => setKind("transferencia")}>
            <ArrowLeftRight size={14} /> Transferencia entre medios
          </Button>
        </div>
        <div className="flex flex-wrap gap-3 items-end">
          <Field label="Fecha">
            <TextInput type="date" value={form.fecha} onChange={(e) => setForm({ ...form, fecha: e.target.value })} required />
          </Field>

          {kind === "motivo" ? (
            <>
              <Field label="Motivo">
                <Select value={form.motivoId} onChange={(e) => setForm({ ...form, motivoId: e.target.value })} style={{ minWidth: 200 }}>
                  {MOTIVOS_MOVIMIENTO.map((m) => <option key={m.id} value={m.id}>{m.label}</option>)}
                </Select>
              </Field>
              {motivo?.requiereCliente && (
                <Field label="Cliente">
                  <Select value={form.clienteId} onChange={(e) => setForm({ ...form, clienteId: e.target.value })} style={{ minWidth: 160 }} required>
                    <option value="">Elegir...</option>
                    {(data.clientes || []).map((c) => <option key={c.id} value={c.id}>{c.nombre}</option>)}
                  </Select>
                </Field>
              )}
              <Field label="Medio de pago">
                <Select value={form.medioPago} onChange={(e) => setForm({ ...form, medioPago: e.target.value })}>
                  {mediosCaja.map((m) => <option key={m} value={m}>{m}</option>)}
                </Select>
              </Field>
            </>
          ) : (
            <>
              <Field label="Desde">
                <Select value={form.medioOrigen} onChange={(e) => setForm({ ...form, medioOrigen: e.target.value })}>
                  {mediosCaja.map((m) => <option key={m} value={m}>{m}</option>)}
                </Select>
              </Field>
              <Field label="Hacia">
                <Select value={form.medioDestino} onChange={(e) => setForm({ ...form, medioDestino: e.target.value })}>
                  {mediosCaja.map((m) => <option key={m} value={m}>{m}</option>)}
                </Select>
              </Field>
            </>
          )}

          <Field label="Monto">
            <MoneyField value={form.monto} onChange={(v) => setForm({ ...form, monto: v })} style={{ width: 110 }} placeholder="0" />
          </Field>
          <Field label="Observaciones">
            <TextInput value={form.observaciones} onChange={(e) => setForm({ ...form, observaciones: e.target.value })} placeholder="Opcional" style={{ width: 180 }} />
          </Field>
          <Button type="button" onClick={submit}><Plus size={15} /> Registrar</Button>
        </div>
        {localError && <div style={{ marginTop: 10, fontSize: 13, color: C.rust, fontWeight: 600 }}>{localError}</div>}
        {justSaved && <div style={{ marginTop: 10, fontSize: 13, color: C.green, fontWeight: 600 }}>✓ Movimiento registrado</div>}
        {kind === "motivo" && motivo && (
          <div style={{ marginTop: 10, fontSize: 12.5, color: C.inkSoft }}>
            {motivo.tipo === "ingreso" ? "Ingreso" : "Egreso"} de caja
            {motivo.flujo && <> · va al Flujo de {motivo.flujo === "inversion" ? "Inversión" : "Financiamiento"}</>}
            {!motivo.flujo && <> · es un ajuste, no afecta los flujos, solo corrige el saldo</>}
          </div>
        )}
      </Card>

      <div>
        <Button variant="ghost" onClick={() => setVerHistorico(!verHistorico)}>
          {verHistorico ? "Ocultar movimientos históricos" : "Ver movimientos históricos"}
        </Button>
      </div>

      {verHistorico && (
        <Card style={{ padding: 0, overflow: "hidden" }}>
          <table style={{ width: "100%", fontSize: 13, borderCollapse: "collapse" }}>
            <thead>
              <tr style={{ background: C.bg, textAlign: "left", color: C.inkSoft }}>
                {["Fecha", "Tipo", "Detalle", "Monto", "Obs.", ""].map((h) => (
                  <th key={h} style={{ padding: "10px 12px", fontWeight: 600 }}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {[...(data.movimientos || [])].sort((a, b) => (a.fecha < b.fecha ? 1 : a.fecha > b.fecha ? -1 : 0)).map((m) => (
                <tr key={m.id} style={{ borderTop: `1px solid ${C.line}` }}>
                  <td style={{ padding: "8px 12px" }}>{m.fecha}</td>
                  <td style={{ padding: "8px 12px" }}>{m.kind === "transferencia" ? "Transferencia" : m.motivoLabel}</td>
                  <td style={{ padding: "8px 12px", color: C.inkSoft }}>
                    {m.kind === "transferencia" ? `${m.medioOrigen} → ${m.medioDestino}` : m.medioPago}
                    {m.clienteNombre && <> · {m.clienteNombre}</>}
                  </td>
                  <td style={{ padding: "8px 12px", fontWeight: 600, color: m.tipo === "egreso" ? C.rust : C.green }}>{money(m.monto)}</td>
                  <td style={{ padding: "8px 12px", color: C.inkSoft }}>{m.observaciones}</td>
                  <td style={{ padding: "8px 12px" }}>
                    <Trash2 size={15} style={{ cursor: "pointer", color: C.inkFaint }} onClick={() => eliminar(m.id)} />
                  </td>
                </tr>
              ))}
              {(data.movimientos || []).length === 0 && (
                <tr><td colSpan={6} style={{ padding: 24, textAlign: "center", color: C.inkFaint }}>Todavía no cargaste ningún movimiento.</td></tr>
              )}
            </tbody>
          </table>
        </Card>
      )}
    </div>
  );
}

/* ---------- Clientes ---------- */
function diasEntreFechas(f1, f2) {
  return Math.abs((new Date(f2) - new Date(f1)) / (1000 * 60 * 60 * 24));
}

function statsCliente(data, clienteId) {
  const ventas = data.ventas.filter((v) => v.clienteId === clienteId).sort((a, b) => (a.fecha < b.fecha ? -1 : 1));
  const cobros = (data.movimientos || []).filter((m) => m.motivoId === "cobro_cta_cte" && m.clienteId === clienteId);
  const totalVentas = ventas.reduce((a, v) => a + v.total, 0);
  const totalCobros = cobros.reduce((a, m) => a + Number(m.monto), 0);
  const saldo = totalVentas - totalCobros;
  const ultimaCompra = ventas.length ? ventas[ventas.length - 1].fecha : null;
  const ticketPromedio = ventas.length ? totalVentas / ventas.length : 0;
  let frecuenciaDias = null;
  if (ventas.length > 1) {
    let sumaDias = 0;
    for (let i = 1; i < ventas.length; i++) sumaDias += diasEntreFechas(ventas[i - 1].fecha, ventas[i].fecha);
    frecuenciaDias = sumaDias / (ventas.length - 1);
  }
  return { ventas, cobros, totalVentas, totalCobros, saldo, ultimaCompra, ticketPromedio, frecuenciaDias };
}

function ClientesView({ data, update }) {
  const [nuevo, setNuevo] = useState(null);
  const [seleccionado, setSeleccionado] = useState(null);
  const [editando, setEditando] = useState(null);

  function crear() {
    if (!nuevo.nombre.trim()) return;
    update({
      ...data,
      clientes: [
        ...(data.clientes || []),
        {
          id: uid(),
          nombre: nuevo.nombre.trim(),
          telefono: nuevo.telefono,
          domicilio: nuevo.domicilio,
          localidad: nuevo.localidad,
          referente: nuevo.referente,
          notas: nuevo.notas,
        },
      ],
    });
    setNuevo(null);
  }
  function eliminar(id) {
    update({ ...data, clientes: (data.clientes || []).filter((c) => c.id !== id) });
    if (seleccionado === id) setSeleccionado(null);
  }
  function guardarEdicion() {
    if (!editando.nombre.trim()) return;
    update({ ...data, clientes: (data.clientes || []).map((c) => (c.id === editando.id ? { ...c, ...editando } : c)) });
    setEditando(null);
  }

  const clienteSel = (data.clientes || []).find((c) => c.id === seleccionado);

  if (clienteSel) {
    const s = statsCliente(data, clienteSel.id);
    const historial = [
      ...s.ventas.map((v) => ({ tipo: "Venta", fecha: v.fecha, detalle: `${v.cantidad} × ${v.productoNombre}`, monto: v.total })),
      ...s.cobros.map((m) => ({ tipo: "Cobro", fecha: m.fecha, detalle: m.observaciones || m.medioPago, monto: -m.monto })),
    ].sort((a, b) => (a.fecha < b.fecha ? 1 : -1));

    return (
      <div className="flex flex-col gap-5">
        <div className="flex items-center gap-2">
          <Button variant="ghost" onClick={() => setSeleccionado(null)}>← Volver</Button>
        </div>
        {editando?.id === clienteSel.id ? (
          <Card style={{ padding: 18 }}>
            <div className="flex flex-wrap gap-3 items-end">
              <Field label="Nombre">
                <TextInput value={editando.nombre} onChange={(e) => setEditando({ ...editando, nombre: e.target.value })} />
              </Field>
              <Field label="Teléfono">
                <TextInput value={editando.telefono || ""} onChange={(e) => setEditando({ ...editando, telefono: e.target.value })} style={{ width: 160 }} />
              </Field>
              <Field label="Domicilio">
                <TextInput value={editando.domicilio || ""} onChange={(e) => setEditando({ ...editando, domicilio: e.target.value })} style={{ width: 180 }} />
              </Field>
              <Field label="Localidad">
                <TextInput value={editando.localidad || ""} onChange={(e) => setEditando({ ...editando, localidad: e.target.value })} style={{ width: 150 }} />
              </Field>
              <Field label="Nombre del referente">
                <TextInput value={editando.referente || ""} onChange={(e) => setEditando({ ...editando, referente: e.target.value })} style={{ width: 160 }} />
              </Field>
              <Button onClick={guardarEdicion}><Check size={15} /> Guardar</Button>
              <Button variant="ghost" onClick={() => setEditando(null)}>Cancelar</Button>
            </div>
          </Card>
        ) : (
          <div className="flex items-center justify-between flex-wrap gap-2">
            <div>
              <h1 style={{ fontSize: 21, fontWeight: 700, color: C.ink, margin: 0 }}>{clienteSel.nombre}</h1>
              <p style={{ fontSize: 13, color: C.inkSoft, margin: "2px 0 0" }}>
                {[clienteSel.telefono, clienteSel.domicilio, clienteSel.localidad].filter(Boolean).join(" · ")}
                {clienteSel.referente && <> · Referente: {clienteSel.referente}</>}
              </p>
            </div>
            <Button variant="ghost" onClick={() => setEditando({ ...clienteSel })}><Pencil size={14} /> Editar datos</Button>
          </div>
        )}
        <div className="flex gap-4 flex-wrap">
          <KPI label="Saldo pendiente" value={money(s.saldo)} accent={s.saldo > 0 ? C.rust : C.green} />
          <KPI label="Última compra" value={s.ultimaCompra || "—"} />
          <KPI label="Ticket promedio" value={money(s.ticketPromedio)} />
          <KPI label="Frecuencia de compra" value={s.frecuenciaDias != null ? `cada ${s.frecuenciaDias.toFixed(0)} días` : "N/D"} />
        </div>
        <Card style={{ padding: 0, overflow: "hidden" }}>
          <table style={{ width: "100%", fontSize: 13, borderCollapse: "collapse" }}>
            <thead>
              <tr style={{ background: C.bg, textAlign: "left", color: C.inkSoft }}>
                {["Fecha", "Tipo", "Detalle", "Monto"].map((h) => <th key={h} style={{ padding: "10px 12px", fontWeight: 600 }}>{h}</th>)}
              </tr>
            </thead>
            <tbody>
              {historial.map((h, i) => (
                <tr key={i} style={{ borderTop: `1px solid ${C.line}` }}>
                  <td style={{ padding: "8px 12px" }}>{h.fecha}</td>
                  <td style={{ padding: "8px 12px" }}>{h.tipo}</td>
                  <td style={{ padding: "8px 12px", color: C.inkSoft }}>{h.detalle}</td>
                  <td style={{ padding: "8px 12px", fontWeight: 600, color: h.monto >= 0 ? C.ink : C.green }}>{money(h.monto)}</td>
                </tr>
              ))}
              {historial.length === 0 && (
                <tr><td colSpan={4} style={{ padding: 24, textAlign: "center", color: C.inkFaint }}>Sin movimientos todavía.</td></tr>
              )}
            </tbody>
          </table>
        </Card>
      </div>
    );
  }

  const resumen = (data.clientes || []).map((c) => ({ cliente: c, ...statsCliente(data, c.id) }));

  return (
    <div className="flex flex-col gap-5">
      <div className="flex items-center justify-between">
        <div>
          <h1 style={{ fontSize: 21, fontWeight: 700, color: C.ink, margin: 0 }}>Clientes</h1>
          <p style={{ fontSize: 13, color: C.inkSoft, margin: "2px 0 0" }}>Cuenta corriente, historial y estadísticas por cliente.</p>
        </div>
        <Button onClick={() => setNuevo({ nombre: "", telefono: "", domicilio: "", localidad: "", referente: "", notas: "" })}><Plus size={15} /> Nuevo cliente</Button>
      </div>

      {nuevo && (
        <Card style={{ padding: 18 }}>
          <div className="flex flex-wrap gap-3 items-end">
            <Field label="Nombre">
              <TextInput value={nuevo.nombre} onChange={(e) => setNuevo({ ...nuevo, nombre: e.target.value })} autoFocus />
            </Field>
            <Field label="Teléfono (opcional)">
              <TextInput value={nuevo.telefono} onChange={(e) => setNuevo({ ...nuevo, telefono: e.target.value })} style={{ width: 160 }} />
            </Field>
            <Field label="Domicilio (opcional)">
              <TextInput value={nuevo.domicilio} onChange={(e) => setNuevo({ ...nuevo, domicilio: e.target.value })} style={{ width: 180 }} />
            </Field>
            <Field label="Localidad (opcional)">
              <TextInput value={nuevo.localidad} onChange={(e) => setNuevo({ ...nuevo, localidad: e.target.value })} style={{ width: 150 }} />
            </Field>
            <Field label="Nombre del referente (opcional)">
              <TextInput value={nuevo.referente} onChange={(e) => setNuevo({ ...nuevo, referente: e.target.value })} style={{ width: 160 }} />
            </Field>
            <Button onClick={crear}><Check size={15} /> Guardar</Button>
            <Button variant="ghost" onClick={() => setNuevo(null)}>Cancelar</Button>
          </div>
        </Card>
      )}

      <Card style={{ padding: 0, overflow: "hidden" }}>
        <table style={{ width: "100%", fontSize: 13, borderCollapse: "collapse" }}>
          <thead>
            <tr style={{ background: C.bg, textAlign: "left", color: C.inkSoft }}>
              {["Cliente", "Teléfono", "Localidad", "Última compra", "Ticket promedio", "Frecuencia", "Saldo", ""].map((h) => (
                <th key={h} style={{ padding: "10px 12px", fontWeight: 600 }}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {resumen.map((r) => (
              <tr key={r.cliente.id} style={{ borderTop: `1px solid ${C.line}`, cursor: "pointer" }} onClick={() => setSeleccionado(r.cliente.id)}>
                <td style={{ padding: "8px 12px", fontWeight: 500 }}>{r.cliente.nombre}</td>
                <td style={{ padding: "8px 12px", color: C.inkSoft }}>{r.cliente.telefono}</td>
                <td style={{ padding: "8px 12px", color: C.inkSoft }}>{r.cliente.localidad}</td>
                <td style={{ padding: "8px 12px" }}>{r.ultimaCompra || "—"}</td>
                <td style={{ padding: "8px 12px" }}>{money(r.ticketPromedio)}</td>
                <td style={{ padding: "8px 12px" }}>{r.frecuenciaDias != null ? `cada ${r.frecuenciaDias.toFixed(0)} días` : "N/D"}</td>
                <td style={{ padding: "8px 12px", fontWeight: 600, color: r.saldo > 0 ? C.rust : C.green }}>{money(r.saldo)}</td>
                <td style={{ padding: "8px 12px" }}>
                  <Trash2 size={15} style={{ cursor: "pointer", color: C.inkFaint }} onClick={(e) => { e.stopPropagation(); eliminar(r.cliente.id); }} />
                </td>
              </tr>
            ))}
            {resumen.length === 0 && (
              <tr><td colSpan={8} style={{ padding: 24, textAlign: "center", color: C.inkFaint }}>Todavía no cargaste ningún cliente.</td></tr>
            )}
          </tbody>
        </table>
      </Card>
    </div>
  );
}

/* ---------- Arqueo de Caja ---------- */
/* ---------- Cobros Pendientes ---------- */
function CobrosPendientes({ data, update }) {
  const mediosConDemora = Object.entries(data.medioConfig || {})
    .filter(([medio, cfg]) => medio !== MEDIO_CTA_CTE && Number(cfg.diasAcreditacion) > 0)
    .map(([medio]) => medio)
    .filter((medio) => data.medios.includes(medio));

  const [medioSel, setMedioSel] = useState(mediosConDemora[0] || "");
  const [seleccion, setSeleccion] = useState({});
  const [montoReal, setMontoReal] = useState("");
  const [fechaReal, setFechaReal] = useState(todayStr());
  const [localError, setLocalError] = useState("");
  const [justSaved, setJustSaved] = useState(false);

  const pendientes = data.ventas.filter((v) => v.medioPago === medioSel && v.estadoCobro === "pendiente" && !v.confirmado);
  const seleccionadas = pendientes.filter((v) => seleccion[v.id]);
  const sumaSeleccionada = seleccionadas.reduce((a, v) => a + v.total, 0);

  function toggle(id) {
    setSeleccion({ ...seleccion, [id]: !seleccion[id] });
  }

  function confirmar() {
    setLocalError("");
    const real = Number(montoReal) || 0;
    if (seleccionadas.length === 0) { setLocalError("Marcá al menos una venta."); return; }
    if (!real) { setLocalError("Indicá el monto realmente acreditado."); return; }
    const comisionReal = sumaSeleccionada - real;
    if (comisionReal < 0) {
      const seguir = window.confirm(
        "El monto acreditado es MAYOR a lo vendido en las ventas marcadas (comisión negativa). ¿Confirmás igual?"
      );
      if (!seguir) return;
    }
    const loteId = uid();
    const idsSeleccionados = new Set(seleccionadas.map((v) => v.id));
    const ventas = data.ventas.map((v) => {
      if (!idsSeleccionados.has(v.id)) return v;
      const comisionMonto = sumaSeleccionada ? (v.total / sumaSeleccionada) * comisionReal : 0;
      return {
        ...v,
        confirmado: true,
        estadoCobro: "acreditado",
        comisionMonto,
        comisionPct: v.total ? (comisionMonto / v.total) * 100 : 0,
        fechaAcreditacionReal: fechaReal,
        loteId,
      };
    });
    const gasto = {
      id: uid(),
      fecha: fechaReal,
      rubro: "Comisiones Corredores de Pago",
      detalle: `Comisión sobre ${seleccionadas.length} venta${seleccionadas.length === 1 ? "" : "s"} acreditadas el ${fechaReal} (${medioSel})`,
      monto: comisionReal,
      medioPago: medioSel,
      observaciones: "",
    };
    update({ ...data, ventas, gastos: [gasto, ...data.gastos] });
    setSeleccion({});
    setMontoReal("");
    setJustSaved(true);
    setTimeout(() => setJustSaved(false), 3000);
  }

  if (mediosConDemora.length === 0) {
    return (
      <Card style={{ padding: 18 }}>
        <div style={{ fontWeight: 600, marginBottom: 6 }}>Cobros pendientes</div>
        <div style={{ fontSize: 13, color: C.inkFaint }}>
          Todavía no configuraste ningún medio de pago con días de acreditación en Configuración, así que no hay nada que revisar acá.
        </div>
      </Card>
    );
  }

  return (
    <Card style={{ padding: 18 }}>
      <div style={{ fontWeight: 600, marginBottom: 4 }}>Cobros pendientes</div>
      <div style={{ fontSize: 12.5, color: C.inkSoft, marginBottom: 12 }}>
        Marcá las ventas que forman parte del mismo depósito bancario, ingresá lo que realmente acreditó tu cuenta, y el sistema calcula la comisión real y la reparte entre esas ventas.
      </div>
      <div className="flex flex-wrap gap-3 items-end" style={{ marginBottom: 12 }}>
        <Field label="Medio de pago">
          <Select value={medioSel} onChange={(e) => { setMedioSel(e.target.value); setSeleccion({}); }}>
            {mediosConDemora.map((m) => <option key={m} value={m}>{m}</option>)}
          </Select>
        </Field>
      </div>

      {pendientes.length === 0 ? (
        <div style={{ fontSize: 13, color: C.inkFaint }}>No hay ventas pendientes de cobro para este medio.</div>
      ) : (
        <>
          <table style={{ width: "100%", fontSize: 13, borderCollapse: "collapse", marginBottom: 12 }}>
            <thead>
              <tr style={{ color: C.inkSoft, textAlign: "left" }}>
                <th style={{ padding: "6px 8px" }}></th>
                <th style={{ padding: "6px 8px" }}>Fecha</th>
                <th style={{ padding: "6px 8px" }}>Producto</th>
                <th style={{ padding: "6px 8px" }}>Fecha estimada</th>
                <th style={{ padding: "6px 8px", textAlign: "right" }}>Monto vendido</th>
              </tr>
            </thead>
            <tbody>
              {pendientes.map((v) => (
                <tr key={v.id} style={{ borderTop: `1px solid ${C.line}` }}>
                  <td style={{ padding: "6px 8px" }}>
                    <input type="checkbox" checked={!!seleccion[v.id]} onChange={() => toggle(v.id)} />
                  </td>
                  <td style={{ padding: "6px 8px" }}>{v.fecha}</td>
                  <td style={{ padding: "6px 8px" }}>{v.productoNombre}</td>
                  <td style={{ padding: "6px 8px", color: C.inkSoft }}>{v.fechaEstimadaAcreditacion}</td>
                  <td style={{ padding: "6px 8px", textAlign: "right" }}>{money(v.total)}</td>
                </tr>
              ))}
            </tbody>
          </table>

          <div className="flex flex-wrap gap-3 items-end">
            <div style={{ fontSize: 13.5 }}>
              Seleccionado: <strong>{money(sumaSeleccionada)}</strong> ({seleccionadas.length} venta{seleccionadas.length === 1 ? "" : "s"})
            </div>
            <Field label="Monto real acreditado">
              <MoneyField value={montoReal} onChange={setMontoReal} style={{ width: 130 }} placeholder="0" />
            </Field>
            <Field label="Fecha real">
              <TextInput type="date" value={fechaReal} onChange={(e) => setFechaReal(e.target.value)} />
            </Field>
            <Button onClick={confirmar}><Check size={15} /> Confirmar acreditación</Button>
          </div>
          {localError && <div style={{ marginTop: 10, fontSize: 13, color: C.rust, fontWeight: 600 }}>{localError}</div>}
          {justSaved && <div style={{ marginTop: 10, fontSize: 13, color: C.green, fontWeight: 600 }}>✓ Acreditación confirmada y comisión registrada</div>}
        </>
      )}
    </Card>
  );
}

function ArqueoView({ data, update }) {
  const [form, setForm] = useState({ desde: todayStr(), hasta: todayStr() });
  const [saldoManual, setSaldoManual] = useState({});
  const mediosCaja = data.medios.filter((m) => m !== MEDIO_CTA_CTE);

  const arqueosOrdenados = useMemo(
    () => [...data.arqueos].sort((a, b) => (a.desde < b.desde ? -1 : 1)),
    [data.arqueos]
  );

  function calcularFila(desde, hasta, saldoInicial) {
    const filtrar = (arr) => arr.filter((it) => it.fecha >= desde && it.fecha <= hasta);
    const movs = filtrar(data.movimientos || []);
    const filas = {};
    mediosCaja.forEach((medio) => {
      let ingresos = filtrar(data.ventas).filter((v) => v.medioPago === medio && estaAcreditadaVenta(v)).reduce((a, v) => a + v.total, 0);
      let egresos = filtrar(data.gastos).filter((g) => g.medioPago === medio).reduce((a, g) => a + Number(g.monto), 0);
      movs.forEach((m) => {
        if (m.kind === "transferencia") {
          if (m.medioOrigen === medio) egresos += Number(m.monto);
          if (m.medioDestino === medio) ingresos += Number(m.monto);
        } else if (m.medioPago === medio) {
          if (m.tipo === "ingreso") ingresos += Number(m.monto);
          else egresos += Number(m.monto);
        }
      });
      const inicial = Number((saldoInicial && saldoInicial[medio]) || 0);
      filas[medio] = { inicial, ingresos, egresos, final: inicial + ingresos - egresos };
    });
    return filas;
  }

  // saldo inicial de un arqueo = saldo final del arqueo anterior (o manual, si es el primero)
  const arqueosCalculados = useMemo(() => {
    let saldoPrevio = null;
    return arqueosOrdenados.map((a) => {
      const inicial = saldoPrevio || a.saldoInicialManual || {};
      const filas = calcularFila(a.desde, a.hasta, inicial);
      const finalPorMedio = {};
      mediosCaja.forEach((m) => (finalPorMedio[m] = filas[m].final));
      saldoPrevio = finalPorMedio;
      return { ...a, filas };
    });
  }, [arqueosOrdenados, data.ventas, data.gastos, data.movimientos, data.medios]); // eslint-disable-line

  function crearArqueo() {
    const esPrimero = data.arqueos.length === 0;
    const nuevo = {
      id: uid(),
      desde: form.desde,
      hasta: form.hasta,
      saldoInicialManual: esPrimero ? saldoManual : null,
    };
    update({ ...data, arqueos: [...data.arqueos, nuevo] });
    setForm({ desde: form.hasta, hasta: todayStr() });
  }
  function eliminarArqueo(id) {
    update({ ...data, arqueos: data.arqueos.filter((a) => a.id !== id) });
  }

  return (
    <div className="flex flex-col gap-5">
      <div>
        <h1 style={{ fontSize: 21, fontWeight: 700, color: C.ink, margin: 0 }}>Arqueo de Caja</h1>
        <p style={{ fontSize: 13, color: C.inkSoft, margin: "2px 0 0" }}>
          El saldo final de cada período pasa solo como saldo inicial del siguiente. Las ventas a "Cuenta Corriente" no suman acá hasta que se cobren.
        </p>
      </div>

      <CobrosPendientes data={data} update={update} />

      <Card style={{ padding: 18 }}>
        <div className="flex flex-wrap gap-3 items-end">
          <Field label="Desde">
            <TextInput type="date" value={form.desde} onChange={(e) => setForm({ ...form, desde: e.target.value })} />
          </Field>
          <Field label="Hasta">
            <TextInput type="date" value={form.hasta} onChange={(e) => setForm({ ...form, hasta: e.target.value })} />
          </Field>
          <Button onClick={crearArqueo}><Plus size={15} /> Nuevo arqueo</Button>
        </div>
        {data.arqueos.length === 0 && (
          <div className="flex flex-wrap gap-3 items-end" style={{ marginTop: 14, paddingTop: 14, borderTop: `1px solid ${C.line}` }}>
            <div style={{ fontSize: 13, color: C.inkSoft, width: "100%" }}>
              Como es el primer arqueo, indicá el saldo inicial real de cada medio de pago (el que tenías antes de empezar a usar la app):
            </div>
            {mediosCaja.map((m) => (
              <Field key={m} label={m}>
                <TextInput
                  type="number"
                  value={saldoManual[m] || ""}
                  onChange={(e) => setSaldoManual({ ...saldoManual, [m]: e.target.value })}
                  style={{ width: 110 }}
                />
              </Field>
            ))}
          </div>
        )}
      </Card>

      {arqueosCalculados.slice().reverse().map((a) => {
        const totalFinal = mediosCaja.reduce((acc, m) => acc + a.filas[m].final, 0);
        return (
          <Card key={a.id} style={{ padding: 18 }}>
            <div className="flex items-center justify-between" style={{ marginBottom: 10 }}>
              <div style={{ fontWeight: 600 }}>{a.desde} → {a.hasta}</div>
              <div className="flex items-center gap-3">
                <div style={{ fontWeight: 700, color: C.green }}>Total: {money(totalFinal)}</div>
                <Trash2 size={15} style={{ cursor: "pointer", color: C.inkFaint }} onClick={() => eliminarArqueo(a.id)} />
              </div>
            </div>
            <table style={{ width: "100%", fontSize: 13, borderCollapse: "collapse" }}>
              <thead>
                <tr style={{ color: C.inkSoft, textAlign: "left" }}>
                  <th style={{ padding: "6px 8px" }}>Medio de pago</th>
                  <th style={{ padding: "6px 8px", textAlign: "right" }}>Saldo inicial</th>
                  <th style={{ padding: "6px 8px", textAlign: "right" }}>Ingresos</th>
                  <th style={{ padding: "6px 8px", textAlign: "right" }}>Egresos</th>
                  <th style={{ padding: "6px 8px", textAlign: "right" }}>Saldo final</th>
                </tr>
              </thead>
              <tbody>
                {mediosCaja.map((m) => (
                  <tr key={m} style={{ borderTop: `1px solid ${C.line}` }}>
                    <td style={{ padding: "6px 8px" }}>{m}</td>
                    <td style={{ padding: "6px 8px", textAlign: "right" }}>{money(a.filas[m].inicial)}</td>
                    <td style={{ padding: "6px 8px", textAlign: "right", color: C.green }}>{money(a.filas[m].ingresos)}</td>
                    <td style={{ padding: "6px 8px", textAlign: "right", color: C.rust }}>{money(a.filas[m].egresos)}</td>
                    <td style={{ padding: "6px 8px", textAlign: "right", fontWeight: 600 }}>{money(a.filas[m].final)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </Card>
        );
      })}
      {data.arqueos.length === 0 && <Empty />}
    </div>
  );
}

/* ---------- Configuración ---------- */
function ConfigView({ data, update }) {
  const [editando, setEditando] = useState(false);
  const [draft, setDraft] = useState(data);

  const view = editando ? draft : data;
  function localUpdate(newData) {
    setDraft(newData);
  }
  function entrarEdicion() {
    setDraft(data);
    setEditando(true);
  }
  function cancelar() {
    setEditando(false);
    setDraft(data);
  }
  function guardar() {
    update(draft);
    setEditando(false);
  }

  function set(key, items) {
    localUpdate({ ...view, [key]: items });
  }
  function make(key, label) {
    const items = view[key];
    return (
      <Card style={{ padding: 18 }}>
        <div style={{ fontWeight: 600, marginBottom: 10 }}>{label}</div>
        <TagList
          items={items}
          onAdd={(v) => set(key, [...items, v])}
          onRemove={(v) => set(key, items.filter((x) => x !== v))}
          editable={editando}
        />
      </Card>
    );
  }

  function setRubroTipo(rubro, tipo) {
    localUpdate({ ...view, rubroTipo: { ...(view.rubroTipo || {}), [rubro]: tipo } });
  }

  return (
    <div className="flex flex-col gap-5">
      <div className="flex items-center justify-between">
        <div>
          <h1 style={{ fontSize: 21, fontWeight: 700, color: C.ink, margin: 0 }}>Configuración</h1>
          <p style={{ fontSize: 13, color: C.inkSoft, margin: "2px 0 0" }}>Estas listas alimentan los menús desplegables de ventas, gastos y productos.</p>
        </div>
        {editando ? (
          <div className="flex gap-2">
            <Button variant="ghost" onClick={cancelar}>Cancelar</Button>
            <Button onClick={guardar}><Check size={15} /> Guardar cambios</Button>
          </div>
        ) : (
          <Button onClick={entrarEdicion}>Editar</Button>
        )}
      </div>

      <Card style={{ padding: 18 }}>
        <div style={{ fontWeight: 600, marginBottom: 10 }}>Datos del negocio</div>
        <div className="flex flex-wrap gap-3 items-end">
          <Field label="Nombre del negocio">
            <TextInput
              value={view.nombreNegocio || ""}
              onChange={(e) => localUpdate({ ...view, nombreNegocio: e.target.value })}
              placeholder="Ej: Lo de María"
              style={{ width: 260 }}
              disabled={!editando}
            />
          </Field>
          <Field label="Link del instructivo (video o página)">
            <TextInput
              value={view.linkInstructivo || ""}
              onChange={(e) => localUpdate({ ...view, linkInstructivo: e.target.value })}
              placeholder="https://..."
              style={{ width: 300 }}
              disabled={!editando}
            />
          </Field>
        </div>
        <div style={{ fontSize: 12, color: C.inkSoft, marginTop: 8 }}>
          El nombre del negocio se usa para nombrar los reportes que descargás, y más adelante para organizar los archivos en Drive.
        </div>
      </Card>

      <Card style={{ padding: 18 }}>
        <div style={{ fontWeight: 600, marginBottom: 4 }}>Nombres de listas de precio</div>
        <div style={{ fontSize: 12, color: C.inkSoft, marginBottom: 10 }}>
          Indicá el nombre de esta lista de precios (por ejemplo, podés cambiar "Otro" por "Distribuidor" o "Kiosco").
        </div>
        <div className="flex flex-wrap gap-3">
          {LISTA_KEYS.map((k) => (
            <Field key={k} label={LISTA_LABEL_DEFAULT[k]}>
              <TextInput
                value={(view.listaLabels || {})[k] || ""}
                onChange={(e) => localUpdate({ ...view, listaLabels: { ...(view.listaLabels || {}), [k]: e.target.value } })}
                style={{ width: 160 }}
                disabled={!editando}
              />
            </Field>
          ))}
        </div>
      </Card>

      <Card style={{ padding: 18 }}>
        <div className="flex items-center justify-between" style={{ marginBottom: 10 }}>
          <div style={{ fontWeight: 600 }}>Descuentos</div>
          <label className="flex items-center gap-2" style={{ fontSize: 13, cursor: editando ? "pointer" : "default" }}>
            <input
              type="checkbox"
              checked={!!view.permitirCombinarDescuentos}
              onChange={(e) => localUpdate({ ...view, permitirCombinarDescuentos: e.target.checked })}
              disabled={!editando}
            />
            Permitir combinar % manual y código en la misma venta
          </label>
        </div>
        <div style={{ fontSize: 12, color: C.inkSoft, marginBottom: 12 }}>
          Códigos de descuento: activalos, desactivalos o renová su vencimiento cuando quieras.
        </div>
        <CodigosDescuento data={view} update={localUpdate} editable={editando} />
      </Card>

      <div className="grid gap-4" style={{ gridTemplateColumns: "1fr 1fr" }}>
        {make("familias", "Familias de productos")}
        {make("puntosVenta", "Puntos de venta")}
        {make("medios", "Medios de pago")}

        <Card style={{ padding: 18 }}>
          <div style={{ fontWeight: 600, marginBottom: 4 }}>Rubros de gastos</div>
          <div style={{ fontSize: 12, color: C.inkSoft, marginBottom: 10 }}>
            Marcá cada rubro como Fijo o Variable — esto se usa para calcular el punto de equilibrio en Indicadores.
          </div>
          <div className="flex flex-col gap-2" style={{ marginBottom: 10 }}>
            {view.rubros.map((r) => (
              <div key={r} className="flex items-center justify-between" style={{ fontSize: 13.5, gap: 8 }}>
                <span className="flex items-center gap-2">
                  {r}
                  {editando && (
                    <X size={13} style={{ cursor: "pointer", color: C.inkFaint }} onClick={() => set("rubros", view.rubros.filter((x) => x !== r))} />
                  )}
                </span>
                <div className="flex gap-1">
                  {["fijo", "variable"].map((t) => (
                    <button
                      key={t}
                      disabled={!editando}
                      onClick={() => setRubroTipo(r, t)}
                      style={{
                        fontSize: 11.5,
                        padding: "3px 9px",
                        borderRadius: 999,
                        border: `1px solid ${C.line}`,
                        cursor: editando ? "pointer" : "default",
                        textTransform: "capitalize",
                        background: (view.rubroTipo || {})[r] === t ? (t === "fijo" ? C.goldSoft : C.greenSoft) : "transparent",
                        color: (view.rubroTipo || {})[r] === t ? C.ink : C.inkSoft,
                      }}
                    >
                      {t}
                    </button>
                  ))}
                </div>
              </div>
            ))}
          </div>
          {editando && <RubroAdder onAdd={(v) => set("rubros", [...view.rubros, v])} />}
        </Card>
      </div>

      <Card style={{ padding: 18 }}>
        <div style={{ fontWeight: 600, marginBottom: 4 }}>Reglas de acreditación por medio de pago</div>
        <div style={{ fontSize: 12, color: C.inkSoft, marginBottom: 12 }}>
          Para medios con cobro diferido (tarjetas, pasarelas de pago), indicá cuántos días tarda en acreditarse y qué comisión estimada cobra. Dejalo en 0 para medios que se cobran al instante (Efectivo, Transferencia).
        </div>
        <div className="flex flex-col gap-2">
          {view.medios.filter((m) => m !== MEDIO_CTA_CTE).map((m) => {
            const cfg = (view.medioConfig || {})[m] || { diasAcreditacion: 0, comisionPct: 0 };
            const setCfg = (campo, valor) =>
              localUpdate({ ...view, medioConfig: { ...(view.medioConfig || {}), [m]: { ...cfg, [campo]: valor } } });
            return (
              <div key={m} className="flex flex-wrap items-end gap-3" style={{ borderTop: `1px solid ${C.line}`, paddingTop: 10 }}>
                <div style={{ minWidth: 130, fontWeight: 500, fontSize: 13.5 }}>{m}</div>
                <Field label="Días hasta acreditación">
                  <TextInput type="number" value={cfg.diasAcreditacion} onChange={(e) => setCfg("diasAcreditacion", Number(e.target.value))} style={{ width: 90 }} disabled={!editando} />
                </Field>
                <Field label="Comisión % estimada">
                  <TextInput type="number" value={cfg.comisionPct} onChange={(e) => setCfg("comisionPct", Number(e.target.value))} style={{ width: 90 }} disabled={!editando} />
                </Field>
                {Number(cfg.diasAcreditacion) > 0 && (
                  <div style={{ fontSize: 11.5, color: C.inkFaint, maxWidth: 340 }}>
                    Los cobros se acreditan automáticamente al flujo de caja en la fecha que indiques acá. Podés revisarlos y ajustarlos en Arqueo de Caja → Cobros pendientes.
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </Card>
    </div>
  );
}
function RubroAdder({ onAdd }) {
  const [val, setVal] = useState("");
  return (
    <div className="flex gap-2">
      <TextInput
        placeholder="Agregar rubro nuevo..."
        value={val}
        onChange={(e) => setVal(e.target.value)}
        onKeyDown={(e) => {
          if (e.key === "Enter" && val.trim()) { onAdd(val.trim()); setVal(""); }
        }}
        style={{ flex: 1 }}
      />
      <Button variant="ghost" onClick={() => { if (val.trim()) { onAdd(val.trim()); setVal(""); } }}>
        <Plus size={15} />
      </Button>
    </div>
  );
}

function CodigosDescuento({ data, update, editable = true }) {
  const [nuevo, setNuevo] = useState({ codigo: "", porcentaje: "", vencimiento: "" });
  const codigos = data.codigosDescuento || [];

  function agregar() {
    if (!nuevo.codigo.trim() || !nuevo.porcentaje) return;
    update({
      ...data,
      codigosDescuento: [...codigos, { id: uid(), codigo: nuevo.codigo.trim().toUpperCase(), porcentaje: Number(nuevo.porcentaje), vencimiento: nuevo.vencimiento, activo: true }],
    });
    setNuevo({ codigo: "", porcentaje: "", vencimiento: "" });
  }
  function actualizar(id, campo, valor) {
    update({ ...data, codigosDescuento: codigos.map((c) => (c.id === id ? { ...c, [campo]: valor } : c)) });
  }
  function eliminar(id) {
    update({ ...data, codigosDescuento: codigos.filter((c) => c.id !== id) });
  }
  function renovar(id) {
    const nuevaFecha = new Date();
    nuevaFecha.setMonth(nuevaFecha.getMonth() + 1);
    actualizar(id, "vencimiento", nuevaFecha.toISOString().slice(0, 10));
    actualizar(id, "activo", true);
  }

  return (
    <div className="flex flex-col gap-3">
      {codigos.map((c) => {
        const vencido = c.vencimiento && c.vencimiento < todayStr();
        return (
          <div key={c.id} className="flex items-center gap-3 flex-wrap" style={{ fontSize: 13.5, padding: "6px 0", borderTop: `1px solid ${C.line}` }}>
            <strong style={{ minWidth: 90 }}>{c.codigo}</strong>
            <span>-{c.porcentaje}%</span>
            <Field label="Vence">
              <TextInput type="date" value={c.vencimiento || ""} onChange={(e) => actualizar(c.id, "vencimiento", e.target.value)} style={{ padding: "4px 8px" }} disabled={!editable} />
            </Field>
            <span style={{ color: vencido ? C.rust : c.activo ? C.green : C.inkFaint, fontWeight: 600 }}>
              {vencido ? "Vencido" : c.activo ? "Activo" : "Inactivo"}
            </span>
            {editable && (
              <Button variant="ghost" style={{ padding: "4px 10px", fontSize: 12 }} onClick={() => actualizar(c.id, "activo", !c.activo)}>
                {c.activo ? "Desactivar" : "Activar"}
              </Button>
            )}
            {editable && vencido && (
              <Button variant="ghost" style={{ padding: "4px 10px", fontSize: 12 }} onClick={() => renovar(c.id)}>Renovar (+1 mes)</Button>
            )}
            {editable && (
              <Trash2 size={15} style={{ cursor: "pointer", color: C.inkFaint, marginLeft: "auto" }} onClick={() => eliminar(c.id)} />
            )}
          </div>
        );
      })}
      {editable && (
        <div className="flex flex-wrap gap-2 items-end" style={{ marginTop: 6 }}>
          <Field label="Código">
            <TextInput value={nuevo.codigo} onChange={(e) => setNuevo({ ...nuevo, codigo: e.target.value })} style={{ width: 120 }} placeholder="VERANO10" />
          </Field>
          <Field label="% descuento">
            <TextInput type="number" value={nuevo.porcentaje} onChange={(e) => setNuevo({ ...nuevo, porcentaje: e.target.value })} style={{ width: 90 }} />
          </Field>
          <Field label="Vencimiento (opcional)">
            <TextInput type="date" value={nuevo.vencimiento} onChange={(e) => setNuevo({ ...nuevo, vencimiento: e.target.value })} />
          </Field>
          <Button onClick={agregar}><Plus size={15} /> Agregar código</Button>
        </div>
      )}
    </div>
  );
}

