/* ---------- App ---------- */
class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { error: null };
  }
  static getDerivedStateFromError(error) {
    return { error };
  }
  componentDidCatch(error, info) {
    console.error("Error de render:", error, info);
  }
  render() {
    if (this.state.error) {
      return (
        <div style={{ padding: 28, fontFamily: FONT_STACK, maxWidth: 560 }}>
          <div style={{ fontWeight: 700, color: C.rust, marginBottom: 8, fontSize: 16 }}>Ocurrió un error inesperado</div>
          <div style={{ fontSize: 13, color: C.inkSoft, marginBottom: 14, fontFamily: "monospace", whiteSpace: "pre-wrap" }}>
            {String(this.state.error?.message || this.state.error)}
          </div>
          <button
            onClick={() => this.setState({ error: null })}
            style={{ padding: "9px 16px", borderRadius: 6, background: C.green, color: "#fff", border: "none", cursor: "pointer" }}
          >
            Reintentar
          </button>
        </div>
      );
    }
    return this.props.children;
  }
}

function ErrorBanner() {
  const [msg, setMsg] = useState(null);
  useEffect(() => {
    const onError = (e) => setMsg(e?.error?.message || e?.message || "Error desconocido");
    const onRejection = (e) => setMsg(String(e?.reason?.message || e?.reason || "Error desconocido"));
    window.addEventListener("error", onError);
    window.addEventListener("unhandledrejection", onRejection);
    return () => {
      window.removeEventListener("error", onError);
      window.removeEventListener("unhandledrejection", onRejection);
    };
  }, []);
  if (!msg) return null;
  return (
    <div
      style={{
        position: "fixed", top: 0, left: 0, right: 0, zIndex: 100,
        background: C.rust, color: "#fff", padding: "10px 16px", fontSize: 13,
        display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12,
      }}
    >
      <span style={{ fontFamily: "monospace" }}>Error: {msg}</span>
      <X size={16} style={{ cursor: "pointer", flexShrink: 0 }} onClick={() => setMsg(null)} />
    </div>
  );
}

// Antes esto se llamaba InnerApp y cargaba sus propios datos desde window.storage.
// Ahora recibe `data` ya cargado y `update` ya conectado a Firestore desde AppRoot.jsx —
// ninguna de las pantallas de adentro (VentasView, GastosView, etc.) tuvo que cambiar.
export function Negocio({ data, update, cabecera }) {
  const [tab, setTab] = useState("dashboard");

  const views = {
    dashboard: <Dashboard data={data} />,
    ventas: <VentasView data={data} update={update} />,
    gastos: <GastosView data={data} update={update} />,
    movimientos: <MovimientosView data={data} update={update} />,
    clientes: <ClientesView data={data} update={update} />,
    arqueo: <ArqueoView data={data} update={update} />,
    productos: <ProductosView data={data} update={update} />,
    importar: <ImportarView data={data} update={update} />,
    config: <ConfigView data={data} update={update} />,
  };

  return (
    <div style={{ display: "flex", minHeight: 640, background: C.bg, fontFamily: FONT_STACK }}>
      <FuenteGoogle />
      <ErrorBanner />
      <Sidebar tab={tab} setTab={setTab} nombreNegocio={data.nombreNegocio} />
      <div style={{ flex: 1, padding: 26, overflowX: "hidden" }}>
        {cabecera}
        {views[tab]}
      </div>
      <AyudaBoton data={data} />
      <MarcaAgua />
    </div>
  );
}

